#damage-flash { background: radial-gradient(ellipse at center, transparent 30%, rgba(129,13,9,.35) 75%, rgba(108,5,4,.75) 100%); transition: opacity .18s ease-out; }
#damage-flash.hit { opacity: 1; transition-duration: .03s; }
#blood-screen { background-image: radial-gradient(circle at 17% 28%, rgba(112,6,3,.5) 0 1%, transparent 3%), radial-gradient(circle at 82% 16%, rgba(119,8,4,.46) 0 1.2%, transparent 4%), radial-gradient(circle at 74% 82%, rgba(128,9,4,.35) 0 1.5%, transparent 5%), radial-gradient(ellipse at center, transparent 34%, rgba(68,2,1,.58) 100%); filter: blur(.3px); opacity: 0; transition: opacity .8s; }
#blood-screen.active { opacity: .78; }
#parry-flash { background: radial-gradient(circle at center, rgba(255,226,166,.34), transparent 46%); mix-blend-mode: screen; }
#parry-flash.on { animation: parryflash .24s ease-out; }
@keyframes parryflash { 0% { opacity: 1; transform: scale(.94); } 100% { opacity: 0; transform: scale(1.04); } }

.screen { position: absolute; inset: 0; z-index: 20; opacity: 0; visibility: hidden; transition: opacity .55s ease, visibility .55s; }
.screen.is-active { opacity: 1; visibility: visible; }
.screen.is-leaving { opacity: 0; visibility: hidden; }

/* ---------- Loading ---------- */
.loading-screen { display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 45%, #19120c 0, #090705 48%, #030202 100%); z-index: 60; }
.loading-screen::before { content: ""; position: absolute; inset: 10% 18%; background: radial-gradient(ellipse, rgba(139,30,23,.12), transparent 65%); filter: blur(40px); }
.load-mark { width: 76px; height: 76px; fill: none; stroke: var(--gold); stroke-width: 1; opacity: .8; animation: sigil-turn 9s linear infinite; }
.load-mark svg { width: 100%; height: 100%; }
@keyframes sigil-turn { to { transform: rotate(360deg); } }
.kicker, .panel-kicker { font-family: var(--sans); letter-spacing: .42em; font-size: 11px; font-weight: 600; color: var(--gold); text-transform: uppercase; }
.loading-screen .kicker { margin: 28px 0 16px; }
.load-track { width: 260px; height: 1px; background: #2c241b; position: relative; overflow: hidden; }
.load-track i { position: absolute; inset: 0; background: linear-gradient(90deg, transparent, var(--gold), var(--blood-bright), transparent); transform: translateX(-100%); animation: loading-bar 1.8s ease-in-out infinite; }
@keyframes loading-bar { 0% { transform: translateX(-100%); } 65% { transform: translateX(100%); } 100% { transform: translateX(100%); } }
.load-sub { margin-top: 13px; color: #6e6559; font-size: 13px; letter-spacing: .14em; text-transform: uppercase; }

/* ---------- Title ---------- */
.title-screen { z-index: 18; background: linear-gradient(90deg, rgba(4,3,2,.8) 0%, rgba(4,3,2,.36) 36%, transparent 62%, rgba(4,3,2,.42) 100%), linear-gradient(0deg, rgba(4,3,2,.84) 0%, transparent 33%, transparent 82%, rgba(4,3,2,.45) 100%); }
.title-screen::before { content: ""; position: absolute; inset: 0; background: radial-gradient(ellipse at 62% 44%, rgba(197,131,61,.09), transparent 38%); mix-blend-mode: screen; pointer-events: none; }
.title-top { position: absolute; top: calc(28px + var(--safe-top)); left: 4.5vw; right: 4.5vw; display: flex; align-items: center; gap: 18px; font-size: 10px; letter-spacing: .38em; color: #8d7d64; }
.title-top::after { content: ""; height: 1px; flex: 1; background: linear-gradient(90deg, var(--line), transparent); }
.title-top .sigil { color: var(--blood-bright); font-size: 8px; }
.title-lockup { position: absolute; left: 6vw; top: 18.5%; width: min(690px, 57vw); }
.eyebrow { margin: 0 0 17px 4px; font-size: 12px; letter-spacing: .55em; color: #b6a98e; font-weight: 500; text-shadow: 0 2px 12px #000; }
.title-lockup h1 { margin: 0; font-family: var(--serif); line-height: .82; font-weight: 900; text-transform: uppercase; letter-spacing: -.055em; color: #e7dcc5; text-shadow: 0 4px 34px rgba(0,0,0,.9), 0 0 90px rgba(191,124,50,.15); }
.title-lockup h1 span { display: block; font-size: clamp(74px, 9.2vw, 154px); }
.title-lockup h1 .title-red { color: var(--blood-bright); margin-left: .54em; text-shadow: 0 4px 34px rgba(0,0,0,.95), 0 0 60px rgba(158,33,19,.24); position: relative; }
.title-lockup h1 .title-red::before { content: ""; position: absolute; left: -.16em; top: 21%; bottom: 12%; width: 1px; background: linear-gradient(transparent, rgba(208,168,104,.55), transparent); }
.title-rule { display: flex; align-items: center; gap: 13px; width: min(430px, 87%); margin: 24px 0 17px; color: var(--gold); }
.title-rule i { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, rgba(190,155,94,.6)); }
.title-rule i:last-child { background: linear-gradient(90deg, rgba(190,155,94,.6), transparent); }
.title-rule b { font-weight: 400; font-size: 14px; opacity: .85; }
.title-sub { margin: 0 0 0 4px; font-family: var(--serif); font-size: clamp(12px, 1.08vw, 16px); color: #aa9b81; letter-spacing: .08em; }
.title-sub em { color: #d5c3a5; font-style: normal; }

.title-menu-wrap { position: absolute; right: 6.2vw; bottom: 21.5%; width: min(390px, 30vw); }
.menu-ornament { display: flex; align-items: center; gap: 12px; margin: 0 0 10px 2px; color: #776b59; font-size: 9px; letter-spacing: .48em; }
.menu-ornament::after { content: ""; flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }
.main-menu { display: flex; flex-direction: column; border-top: 1px solid var(--line); }
.menu-btn { --fill: 0; display: grid; grid-template-columns: 40px 1fr auto; align-items: center; min-height: 58px; padding: 0 13px 0 9px; border: 0; border-bottom: 1px solid rgba(181,141,79,.15); background: transparent; text-align: left; cursor: pointer; position: relative; overflow: hidden; transition: color .24s, padding .24s; }
.menu-btn::before { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(128,26,18,.42), rgba(128,26,18,.05) 74%, transparent); transform: scaleX(var(--fill)); transform-origin: left; transition: transform .33s cubic-bezier(.2,.7,.2,1); }
.menu-btn::after { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 2px; background: var(--blood-bright); transform: scaleY(0); transition: transform .25s; }
.menu-btn:hover, .menu-btn:focus-visible { --fill: 1; padding-left: 16px; outline: none; }
.menu-btn:hover::after, .menu-btn:focus-visible::after { transform: scaleY(1); }
.menu-btn.primary .menu-label { color: var(--bone); }
.menu-index { position: relative; font-family: var(--serif); font-size: 10px; color: var(--gold); opacity: .7; }
.menu-label { position: relative; font-family: var(--serif); font-size: clamp(12px, 1.1vw, 16px); letter-spacing: .2em; color: #c8bca7; font-weight: 600; }
.menu-note { position: relative; font-size: 9px; letter-spacing: .25em; color: #6f6454; }
.menu-btn.primary .menu-note { color: var(--blood-bright); }

.title-loadout { position: absolute; left: 6vw; bottom: 11.7%; width: min(315px, 24vw); padding: 16px 0; border-top: 1px solid var(--line); border-bottom: 1px solid rgba(181,141,79,.13); }
.title-loadout .panel-kicker { font-size: 9px; }
.loadout-row { display: flex; align-items: center; gap: 14px; margin: 11px 0 13px; }
.weapon-glyph { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid rgba(181,141,79,.26); background: linear-gradient(145deg, rgba(181,141,79,.1), transparent); color: #d3c29e; font-size: 19px; transform: rotate(-8deg); }
.loadout-row strong { display: block; font-family: var(--serif); font-size: 12px; letter-spacing: .12em; color: #dbd0bc; font-weight: 600; }
.loadout-row span { display: block; margin-top: 5px; font-size: 10px; letter-spacing: .17em; color: #7d7362; }
.progress-line { height: 2px; background: rgba(255,255,255,.07); }
.progress-line i { display: block; height: 100%; background: linear-gradient(90deg, var(--blood), var(--gold)); }
.progress-meta { display: flex; justify-content: space-between; margin-top: 7px; color: #6e6455; font-size: 9px; letter-spacing: .22em; }

.title-footer { position: absolute; left: 4.5vw; right: 4.5vw; bottom: calc(24px + var(--safe-bottom)); display: flex; justify-content: space-between; align-items: center; font-size: 9px; letter-spacing: .23em; color: #665d50; }
.footer-mid { display: flex; align-items: center; gap: 12px; color: #8f8169; }
.footer-mid i { width: 3px; height: 3px; background: var(--blood-bright); transform: rotate(45deg); }

/* ---------- HUD ---------- */
.hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; opacity: 0; transition: opacity .65s ease; }
body.in-game .hud { opacity: 1; }
body.in-game .title-screen { opacity: 0; visibility: hidden; }
.hud-top-left { position: absolute; top: calc(31px + var(--safe-top)); left: 3.1vw; display: flex; gap: 12px; align-items: flex-start; filter: drop-shadow(0 2px 8px rgba(0,0,0,.8)); }
.portrait-mark { width: 43px; height: 52px; border: 1px solid rgba(195,160,97,.33); background: linear-gradient(160deg, rgba(168,48,28,.2), rgba(6,5,4,.7)); clip-path: polygon(50% 0, 100% 12%, 100% 78%, 50% 100%, 0 78%, 0 12%); display: grid; place-items: center; }
.portrait-mark span { font-family: var(--serif); color: var(--gold); font-size: 17px; }
.vitals { width: clamp(190px, 15.5vw, 260px); }
.vital { position: relative; margin-bottom: 6px; }
.vital-label { position: absolute; top: -1px; left: 8px; z-index: 2; font-size: 8px; letter-spacing: .3em; color: #d3c5ab; text-shadow: 0 1px 4px #000; }
.bar { height: 14px; background: rgba(4,3,2,.72); border: 1px solid rgba(192,159,100,.21); position: relative; overflow: hidden; transform: skewX(-15deg); }
.bar i { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; transition: width .14s ease-out; }
.bar em { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; background: rgba(222,210,185,.2); transition: width .75s ease; }
.health .bar i { background: linear-gradient(90deg, #5f100b, #a6261a 54%, #c8452f); box-shadow: 0 0 13px rgba(198,59,40,.5); }
.stamina .bar { height: 6px; }
.stamina .bar i { background: linear-gradient(90deg, #6c6540, #c2ad6d); }
.health-text { position: absolute; right: 7px; top: -1px; z-index: 2; font-size: 10px; font-weight: 600; color: #e8dcc2; }
.status-chips { display: flex; gap: 7px; margin-top: 5px; }
.status-chips span { font-size: 8px; letter-spacing: .2em; padding: 2px 6px; background: rgba(0,0,0,.35); border: 1px solid rgba(174,145,91,.18); color: #968872; }

.hud-top-center { position: absolute; top: calc(26px + var(--safe-top)); left: 50%; transform: translateX(-50%); text-align: center; filter: drop-shadow(0 2px 10px #000); }
.hud-top-center p { margin: 0 0 2px; color: #95866f; font-size: 9px; letter-spacing: .44em; }
.hud-top-center strong { display: block; font-family: var(--serif); font-size: 20px; letter-spacing: .28em; color: #dfd1b7; font-weight: 600; }
.hud-top-center span { display: block; margin-top: 4px; color: #756957; font-size: 8px; letter-spacing: .31em; }
.wave-pips { display: flex; justify-content: center; gap: 5px; margin-top: 8px; }
.wave-pips i { width: 13px; height: 2px; background: rgba(195,163,103,.18); }
.wave-pips i.filled { background: var(--gold); box-shadow: 0 0 6px rgba(181,141,79,.5); }
.wave-pips i.boss { background: var(--blood); }
.hud-top-right { position: absolute; top: calc(31px + var(--safe-top)); right: 3.1vw; text-align: right; filter: drop-shadow(0 2px 8px rgba(0,0,0,.8)); }
.score-block span { display: block; color: #776c5a; font-size: 8px; letter-spacing: .32em; }
.score-block b { display: block; font-family: var(--serif); font-size: 18px; letter-spacing: .11em; color: #d9cbb3; font-weight: 600; }
.score-block.small { margin-top: 8px; }
.score-block.small b { color: var(--gold); font-size: 13px; }

.boss-hud { position: absolute; top: calc(99px + var(--safe-top)); left: 50%; transform: translateX(-50%) translateY(-12px); width: min(580px, 54vw); opacity: 0; transition: opacity .4s, transform .4s; text-align: center; }
.boss-hud.active { opacity: 1; transform: translateX(-50%) translateY(0); }
.boss-title { display: flex; align-items: baseline; justify-content: center; gap: 12px; margin-bottom: 5px; }
.boss-title span { font-size: 8px; letter-spacing: .3em; color: var(--blood-bright); }
.boss-title b { font-family: var(--serif); font-size: 14px; letter-spacing: .17em; color: #e1d3b9; }
.boss-bar { height: 5px; background: rgba(0,0,0,.65); border: 1px solid rgba(181,141,79,.25); padding: 1px; }
.boss-bar i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #74120d, #bd3322 65%, #e37a45); box-shadow: 0 0 9px rgba(198,59,40,.5); transition: width .16s; }
.boss-rule { margin: 4px 0 0; font-size: 7px; letter-spacing: .26em; color: #766a58; }

.reticle { position: absolute; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%); opacity: .8; transition: transform .15s, opacity .2s; }
.reticle i, .reticle b { position: absolute; left: 50%; top: 50%; background: rgba(223,211,188,.8); box-shadow: 0 0 4px rgba(0,0,0,.8); }
.reticle i { width: 1px; height: 6px; transform: translate(-50%, -50%); }
.reticle b { width: 6px; height: 1px; transform: translate(-50%, -50%); }
.reticle em { position: absolute; inset: 3px; border: 1px solid rgba(216,198,163,.13); border-radius: 50%; }
.reticle.lock { transform: translate(-50%, -50%) scale(.75); opacity: 1; }
.reticle.lock i, .reticle.lock b { background: var(--blood-bright); }
.reticle.lock em { border-color: rgba(198,59,40,.45); }

.hud-bottom-left { position: absolute; left: 3.1vw; bottom: calc(42px + var(--safe-bottom)); display: flex; gap: 16px; align-items: flex-end; filter: drop-shadow(0 3px 10px #000); }
.weapon-card { width: 200px; padding: 9px 11px 8px; background: linear-gradient(100deg, rgba(7,6,5,.7), rgba(7,6,5,.25)); border-left: 2px solid rgba(181,141,79,.42); }
.weapon-card .panel-kicker { font-size: 7px; color: #84745e; }
.weapon-card strong { display: block; margin: 3px 0 7px; font-family: var(--serif); font-size: 11px; letter-spacing: .12em; color: #d7c8ad; }
.weapon-stat-line { display: flex; align-items: center; gap: 6px; color: #716657; font-size: 7px; letter-spacing: .18em; }
.weapon-stat-line i { flex: 1; height: 2px; background: rgba(255,255,255,.08); }
.weapon-stat-line b { display: block; height: 100%; background: var(--gold); }
.chain-card { padding-bottom: 1px; }
.chain-card span { display: block; color: #756a58; font-size: 7px; letter-spacing: .26em; }
.chain-card b { display: block; font-family: var(--serif); font-size: 25px; font-weight: 600; color: #bda87e; line-height: 1; }
.chain-card em { display: block; width: 46px; height: 1px; margin-top: 5px; background: var(--blood-bright); transform-origin: left; }

.hud-bottom-right { position: absolute; right: 3.1vw; bottom: calc(42px + var(--safe-bottom)); width: min(220px, 17vw); text-align: right; filter: drop-shadow(0 3px 10px #000); }
.rage-caption { display: flex; justify-content: flex-end; align-items: baseline; gap: 8px; }
.rage-caption span { font-size: 8px; letter-spacing: .3em; color: #8d7a60; }
.rage-caption b { font-family: var(--serif); font-size: 13px; color: var(--gold); }
.rage-bar { height: 5px; margin: 4px 0 5px; background: rgba(0,0,0,.6); border: 1px solid rgba(181,141,79,.2); }
.rage-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #7c1a12, #e36332); box-shadow: 0 0 8px rgba(227,99,50,.5); transition: width .25s; }
.rage-hint { font-size: 7px; letter-spacing: .2em; color: #6d6253; }
.stamina-warning { margin-top: 7px; font-family: var(--serif); font-size: 10px; letter-spacing: .16em; color: var(--blood-bright); opacity: 0; transition: opacity .2s; }
.stamina-warning.on { opacity: 1; animation: pulse .7s infinite alternate; }
@keyframes pulse { to { opacity: .4; } }

.control-ribbon { position: absolute; bottom: calc(14px + var(--safe-bottom)); left: 50%; transform: translateX(-50%); display: flex; gap: 18px; padding: 5px 13px; background: rgba(3,2,2,.26); border-top: 1px solid rgba(181,141,79,.1); opacity: .58; transition: opacity 1s; white-space: nowrap; }
.control-ribbon.hide { opacity: 0; }
.control-ribbon span { font-size: 7px; letter-spacing: .19em; color: #736755; }
.control-ribbon b { color: #aa9980; font-weight: 600; margin-right: 3px; }

.announcement { position: absolute; top: 31%; left: 50%; transform: translate(-50%, -20px); text-align: center; opacity: 0; width: 100%; transition: opacity .5s, transform .5s; }
.announcement.show { opacity: 1; transform: translate(-50%, 0); }
.announcement span { display: block; font-size: 9px; letter-spacing: .55em; color: var(--blood-bright); }
.announcement strong { display: block; margin: 6px 0 2px; font-family: var(--serif); font-size: clamp(30px, 3.6vw, 52px); letter-spacing: .15em; color: #e6d8be; font-weight: 900; text-shadow: 0 4px 24px #000; }
.announcement p { margin: 0; font-size: 9px; letter-spacing: .4em; color: #8e7f68; }
.announcement.boss strong { color: #e1b3a1; }

.execution-prompt { position: absolute; left: 50%; top: 61%; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; opacity: 0; transition: opacity .2s; }
.execution-prompt.show { opacity: 1; }
.execution-prompt b { width: 24px; height: 24px; display: grid; place-items: center; border: 1px solid rgba(224,203,168,.7); background: rgba(111,19,13,.8); font-family: var(--serif); font-size: 11px; color: #efe2c9; }
.execution-prompt span { font-size: 9px; letter-spacing: .33em; color: #d8c6a8; text-shadow: 0 2px 8px #000; }
#slowmo-vignette { position: absolute; inset: 0; opacity: 0; background: radial-gradient(circle at 50% 47%, transparent 16%, rgba(6,2,1,.5) 66%, rgba(3,1,1,.86) 100%); transition: opacity .25s; }
#slowmo-vignette.on { opacity: 1; }
#hit-marker { position: absolute; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%) scale(1.5); border: 1px solid rgba(255,238,210,.9); opacity: 0; }
#hit-marker.on { animation: hitmark .18s ease-out; }
@keyframes hitmark { 0% { opacity: 1; transform: translate(-50%, -50%) scale(.55) rotate(45deg); } 100% { opacity: 0; transform: translate(-50%, -50%) scale(1.2) rotate(45deg); } }

.enemy-layer, .float-layer, .target-layer { position: absolute; inset: 0; overflow: hidden; }
.enemy-bar { position: absolute; width: 96px; transform: translate(-50%, -100%); opacity: 0; transition: opacity .18s; }
.enemy-bar.show { opacity: 1; }
.enemy-bar .name { display: flex; justify-content: space-between; margin-bottom: 3px; color: #bfae92; font-size: 7px; letter-spacing: .17em; white-space: nowrap; text-shadow: 0 1px 3px #000; }
.enemy-bar .name b { color: #9d8a6f; font-weight: 400; }
.enemy-bar .track { height: 3px; background: rgba(0,0,0,.7); border: 1px solid rgba(156,127,78,.25); padding: 1px; }
.enemy-bar .track i { display: block; height: 100%; background: linear-gradient(90deg, #781510, #bd3b26); transition: width .12s; }
.enemy-bar.boss { width: 140px; }
.enemy-bar.boss .name { color: #e0bca4; }
.enemy-bar .guard { height: 2px; margin-top: 2px; background: rgba(100,120,124,.5); width: 0%; }
.float-num { position: absolute; transform: translate(-50%, -50%); color: #e7d8bd; font-family: var(--serif); font-size: 15px; text-shadow: 0 2px 5px #000; opacity: 0; animation: floatnum .7s ease-out forwards; }
.float-num.crit { color: #ff7a4a; font-size: 20px; }
.float-num.block { color: #c2d0d1; font-size: 11px; letter-spacing: .1em; }
.float-num.heal { color: #9dc78a; }
@keyframes floatnum { 0% { opacity: 0; margin-top: 8px; } 15% { opacity: 1; } 100% { opacity: 0; margin-top: -48px; } }
.target-mark { position: absolute; width: 32px; height: 32px; transform: translate(-50%,-50%); border: 1px solid rgba(198,59,40,.55); border-radius: 50%; opacity: 0; }
.target-mark.show { opacity: 1; }
.target-mark::before, .target-mark::after { content: ""; position: absolute; background: rgba(219,201,166,.65); }
.target-mark::before { left: 50%; top: -4px; width: 1px; height: 7px; }
.target-mark::after { left: 50%; bottom: -4px; width: 1px; height: 7px; }

/* ---------- Touch ---------- */
.touch-ui { position: absolute; inset: 0; z-index: 14; display: none; pointer-events: none; }
body.touch.in-game .touch-ui { display: block; }
.joystick { position: absolute; left: max(22px, env(safe-area-inset-left)); bottom: calc(34px + var(--safe-bottom)); width: 116px; height: 116px; border: 1px solid rgba(203,178,133,.18); border-radius: 50%; background: radial-gradient(circle, rgba(20,15,11,.28), rgba(5,4,3,.14)); pointer-events: auto; touch-action: none; }
.joystick i { position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; border: 1px solid rgba(201,174,127,.35); border-radius: 50%; transform: translate(-50%, -50%); background: rgba(20,15,11,.28); }
.joystick b { position: absolute; left: 50%; top: 50%; width: 9px; height: 9px; margin: -4px; background: rgba(205,178,129,.6); border-radius: 50%; }
.touch-actions { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: calc(34px + var(--safe-bottom)); width: 202px; height: 174px; pointer-events: none; }
.touch-actions button { position: absolute; border: 1px solid rgba(215,188,143,.25); background: rgba(12,9,7,.45); border-radius: 50%; color: #c7b89e; font-family: var(--sans); font-size: 8px; letter-spacing: .12em; pointer-events: auto; touch-action: none; backdrop-filter: blur(2px); }
.touch-actions button:active { background: rgba(133,28,18,.6); }
.touch-actions .attack { width: 76px; height: 76px; right: 0; bottom: 18px; }
.touch-actions .heavy { width: 52px; height: 52px; right: 84px; bottom: 42px; }
.touch-actions .block { width: 52px; height: 52px; right: 18px; bottom: 101px; }
.touch-actions .dodge { width: 44px; height: 44px; right: 96px; bottom: 108px; }
.touch-actions .execute { width: 60px; height: 60px; left: 0; top: 0; display: none; border-color: rgba(200,64,43,.55); color: #f0b9a3; }
.touch-actions .execute.show { display: block; }
.touch-look-hint { position: absolute; right: 20px; top: 46%; color: rgba(213,196,166,.4); font-size: 8px; letter-spacing: .2em; transform: rotate(90deg); transform-origin: right; }

