import * as THREE from 'three'

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const invLerp = (a, b, v) => clamp((v - a) / (b - a), 0, 1)
export const smoothstep = (a, b, v) => { const t = invLerp(a, b, v); return t * t * (3 - 2 * t) }
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt))
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const pick = arr => arr[Math.floor(Math.random() * arr.length)]
export const chance = p => Math.random() < p
export const deg = d => d * Math.PI / 180

export function dampAngle(current, target, lambda, dt) {
  let diff = ((target - current + Math.PI) % (Math.PI * 2)) - Math.PI
  if (diff < -Math.PI) diff += Math.PI * 2
  return current + diff * (1 - Math.exp(-lambda * dt))
}

export function shortestAngle(a, b) {
  let d = ((b - a + Math.PI) % (Math.PI * 2)) - Math.PI
  if (d < -Math.PI) d += Math.PI * 2
  return d
}

export function angleDiff(a, b) {
  return Math.abs(shortestAngle(a, b))
}

export function seededRandom(seed = 1) {
  let s = seed >>> 0
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0
    return s / 4294967296
  }
}

export function makePeriodicNoise(seed = 8) {
  const rng = seededRandom(seed)
  const grid = Array.from({ length: 64 * 64 }, rng)
  const at = (x, y) => grid[((y & 63) * 64) + (x & 63)]
  return (x, y, scale = 64) => {
    const sx = x / scale
    const sy = y / scale
    const x0 = Math.floor(sx)
    const y0 = Math.floor(sy)
    const tx = sx - x0
    const ty = sy - y0
    const u = tx * tx * (3 - 2 * tx)
    const v = ty * ty * (3 - 2 * ty)
    return lerp(lerp(at(x0, y0), at(x0 + 1, y0), u), lerp(at(x0, y0 + 1), at(x0 + 1, y0 + 1), u), v)
  }
}

export function seededNoise2D(seed = 1) {
  const hash = (x, y) => {
    let n = Math.sin(x * 127.1 + y * 311.7 + seed * 74.7) * 43758.5453
    return n - Math.floor(n)
  }
  return (x, y) => {
    const xi = Math.floor(x)
    const yi = Math.floor(y)
    const xf = x - xi
    const yf = y - yi
    const u = xf * xf * (3 - 2 * xf)
    const v = yf * yf * (3 - 2 * yf)
    return lerp(lerp(hash(xi, yi), hash(xi + 1, yi), u), lerp(hash(xi, yi + 1), hash(xi + 1, yi + 1), u), v)
  }
}

export function fbm(noise, x, y, octaves = 4) {
  let sum = 0
  let amp = .5
  let freq = 1
  for (let i = 0; i < octaves; i++) {
    sum += noise(x * freq, y * freq) * amp
    freq *= 2
    amp *= .5
  }
  return sum
}

export function formatNumber(n) {
  return Math.max(0, Math.floor(n)).toLocaleString('en-US')
}

export function roman(n) {
  const table = [[1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']]
  let out = ''
  for (const [value, symbol] of table) while (n >= value) { out += symbol; n -= value }
  return out || 'I'
}

export function disposeObject(obj) {
  obj.traverse(child => {
    if (child.geometry) child.geometry.dispose()
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material]
      for (const mat of mats) {
        if (mat.map) mat.map.dispose()
        mat.dispose()
      }
    }
  })
}

export function setShadow(root, cast = true, receive = true) {
  root.traverse(o => {
    if (o.isMesh) { o.castShadow = cast; o.receiveShadow = receive }
  })
}

import * as THREE from 'three'
import { fbm, seededNoise2D, seededRandom, clamp } from './utils.js'

function canvas(size = 512) {
  const c = document.createElement('canvas')
  c.width = c.height = size
  return [c, c.getContext('2d')]
}

function texture(c, repeat = 1, srgb = true) {
  const tex = new THREE.CanvasTexture(c)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(repeat, repeat)
  tex.anisotropy = 4
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createStoneTexture(variant = 0, size = 512) {
  const [c, ctx] = canvas(size)
  const img = ctx.createImageData(size, size)
  const noise = seededNoise2D(12 + variant)
  const base = variant === 2 ? [31, 29, 29] : variant === 1 ? [43, 42, 39] : [66, 58, 48]
  const rng = seededRandom(23 + variant)
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = fbm(noise, x / 46, y / 46, 5)
      const fine = fbm(noise, x / 8, y / 8, 2)
      const grain = (rng() - .5) * 18
      const v = (n * 34 + fine * 21 + grain) * (variant === 2 ? .64 : 1)
      const i = (y * size + x) * 4
      img.data[i] = clamp(base[0] + v, 0, 255)
      img.data[i + 1] = clamp(base[1] + v * .93, 0, 255)
      img.data[i + 2] = clamp(base[2] + v * .82, 0, 255)
      img.data[i + 3] = 255
    }
  }
  ctx.putImageData(img, 0, 0)
  ctx.globalAlpha = .25
  for (let i = 0; i < 90; i++) {
    const x = rng() * size
    const y = rng() * size
    const r = 4 + rng() * 28
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, variant === 0 ? '#0a0907' : '#080808')
    g.addColorStop(1, 'rgba(0,0,0,0)')
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  ctx.globalAlpha = 1
  if (variant === 0) {
    ctx.strokeStyle = 'rgba(40,45,28,.2)'
    ctx.lineWidth = 1
    for (let i = 0; i < 20; i++) {
      ctx.beginPath()
      let x = rng() * size, y = rng() * size
      ctx.moveTo(x, y)
      for (let j = 0; j < 8; j++) { x += (rng() - .5) * 36; y += (rng() - .2) * 26; ctx.lineTo(x, y) }
      ctx.stroke()
    }
  }
  ctx.strokeStyle = variant === 2 ? 'rgba(154,58,21,.18)' : 'rgba(13,11,9,.38)'
  ctx.lineWidth = 1.5
  for (let i = 0; i < 13; i++) {
    ctx.beginPath()
    let x = rng() * size, y = rng() * size
    ctx.moveTo(x, y)
    for (let j = 0; j < 10; j++) { x += (rng() - .5) * 48; y += rng() * 34; ctx.lineTo(x, y) }
    ctx.stroke()
  }
  return texture(c, 1)
}

export function createSandTexture(size = 512) {
  const [c, ctx] = canvas(size)
  const img = ctx.createImageData(size, size)
  const n1 = seededNoise2D(72)
  const n2 = seededNoise2D(46)
  const rng = seededRandom(19)
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const broad = fbm(n1, x / 38, y / 38, 4)
      const ripple = Math.sin((x + fbm(n2, x / 30, y / 30, 2) * 80) * .11) * .5 + .5
      const grain = (rng() - .5) * 30
      const v = (broad - .5) * 28 + ripple * 14 + grain
      const i = (y * size + x) * 4
      img.data[i] = clamp(118 + v, 0, 255)
      img.data[i + 1] = clamp(99 + v * .89, 0, 255)
      img.data[i + 2] = clamp(72 + v * .7, 0, 255)
      img.data[i + 3] = 255
    }
  }
  ctx.putImageData(img, 0, 0)
  ctx.globalAlpha = .14
  for (let i = 0; i < 38; i++) {
    const x = rng() * size, y = rng() * size, r = 10 + rng() * 32
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, '#3a2719'); g.addColorStop(1, 'rgba(58,39,25,0)')
    ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  ctx.globalAlpha = 1
  return texture(c, 1)
}

export function createBasaltTexture(size = 512) {
  const [c, ctx] = canvas(size)
  const img = ctx.createImageData(size, size)
  const noise = seededNoise2D(112)
  const rng = seededRandom(81)
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const n = fbm(noise, x / 28, y / 28, 5)
      const grain = (rng() - .5) * 16
      const v = n * 31 + grain
      const i = (y * size + x) * 4
      img.data[i] = clamp(31 + v, 0, 255)
      img.data[i + 1] = clamp(27 + v * .82, 0, 255)
      img.data[i + 2] = clamp(26 + v * .78, 0, 255)
      img.data[i + 3] = 255
    }
  }
  ctx.putImageData(img, 0, 0)
  ctx.lineCap = 'round'
  for (let i = 0; i < 22; i++) {
    ctx.beginPath()
    let x = rng() * size, y = rng() * size
    ctx.moveTo(x, y)
    for (let j = 0; j < 12; j++) { x += (rng() - .5) * 30; y += rng() * 27; ctx.lineTo(x, y) }
    ctx.strokeStyle = `rgba(${70 + rng() * 35 | 0},${27 + rng() * 13 | 0},14,.35)`
    ctx.lineWidth = .6 + rng() * 1.6
    ctx.stroke()
  }
  return texture(c, 1)
}

export function createLavaGlowTexture(size = 512) {
  const [c, ctx] = canvas(size)
  ctx.fillStyle = '#000'
  ctx.fillRect(0, 0, size, size)
  const rng = seededRandom(22)
  ctx.lineCap = 'round'
  for (let i = 0; i < 16; i++) {
    ctx.beginPath()
    let x = rng() * size, y = rng() * size
    ctx.moveTo(x, y)
    for (let j = 0; j < 14; j++) { x += (rng() - .5) * 45; y += rng() * 30; ctx.lineTo(x, y) }
    ctx.strokeStyle = `rgba(${190 + rng() * 60 | 0},${55 + rng() * 80 | 0},18,${.25 + rng() * .45})`
    ctx.lineWidth = 1 + rng() * 4
    ctx.shadowColor = '#ff4d18'
    ctx.shadowBlur = 7
    ctx.stroke()
  }
  ctx.shadowBlur = 0
  return texture(c, 1)
}

export function createBannerTexture(index = 0, size = 512) {
  const [c, ctx] = canvas(size)
  const palettes = [
    ['#4b110e', '#1b0907', '#b28a51'],
    ['#232a2d', '#0d1011', '#788987'],
    ['#3f0b08', '#120504', '#a86f3d']
  ]
  const p = palettes[index % palettes.length]
  const grad = ctx.createLinearGradient(0, 0, 0, size)
  grad.addColorStop(0, p[0]); grad.addColorStop(.72, p[1]); grad.addColorStop(1, '#080504')
  ctx.fillStyle = grad; ctx.fillRect(0, 0, size, size)
  ctx.globalAlpha = .25
  const rng = seededRandom(90 + index)
  for (let i = 0; i < 120; i++) {
    ctx.fillStyle = i % 2 ? '#000' : '#fff'
    ctx.fillRect(rng() * size, rng() * size, rng() * 2, 26 + rng() * 80)
  }
  ctx.globalAlpha = 1
  ctx.strokeStyle = p[2]
  ctx.lineWidth = 2
  ctx.strokeRect(20, 20, size - 40, size - 40)
  ctx.lineWidth = 1
  ctx.strokeRect(28, 28, size - 56, size - 56)
  ctx.translate(size / 2, size * .39)
  ctx.fillStyle = p[2]
  ctx.globalAlpha = .78
  ctx.beginPath()
  ctx.arc(0, 0, 67, 0, Math.PI * 2)
  ctx.strokeStyle = p[2]; ctx.lineWidth = 4; ctx.stroke()
  ctx.beginPath()
  ctx.moveTo(-43, -18); ctx.quadraticCurveTo(-26, -54, 0, -55); ctx.quadraticCurveTo(26, -54, 43, -18)
  ctx.lineTo(33, 15); ctx.quadraticCurveTo(20, 40, 0, 49); ctx.quadraticCurveTo(-20, 40, -33, 15); ctx.closePath()
  ctx.fill()
  ctx.fillStyle = '#110705'
  ctx.beginPath(); ctx.ellipse(-17, -7, 12, 8, .2, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.ellipse(17, -7, 12, 8, -.2, 0, 7); ctx.fill()
  ctx.beginPath(); ctx.moveTo(0, 3); ctx.lineTo(-7, 21); ctx.lineTo(7, 21); ctx.closePath(); ctx.fill()
  ctx.fillRect(-21, 28, 42, 5)
  ctx.strokeStyle = p[2]; ctx.lineWidth = 3
  ctx.beginPath(); ctx.moveTo(-95, 112); ctx.lineTo(95, 112); ctx.stroke()
  ctx.globalAlpha = .65
  ctx.beginPath(); ctx.moveTo(0, 66); ctx.lineTo(-9, 94); ctx.lineTo(0, 122); ctx.lineTo(9, 94); ctx.closePath(); ctx.fill()
  ctx.globalAlpha = 1
  ctx.translate(-size / 2, -size * .39)
  // ragged bottom
  ctx.globalCompositeOperation = 'destination-out'
  for (let x = 0; x < size; x += 8) {
    const h = 7 + rng() * 22
    ctx.fillRect(x, size - h, 9, h)
  }
  ctx.globalCompositeOperation = 'source-over'
  return texture(c, 1)
}

export function createBloodSplatTexture(size = 256) {
  const [c, ctx] = canvas(size)
  ctx.clearRect(0, 0, size, size)
  const rng = seededRandom(67)
  const cx = size / 2, cy = size / 2
  for (let i = 0; i < 30; i++) {
    const x = cx + (rng() - .5) * size * .55
    const y = cy + (rng() - .5) * size * .55
    const r = 4 + rng() * 30
    const g = ctx.createRadialGradient(x, y, 1, x, y, r)
    g.addColorStop(0, 'rgba(73,4,3,.94)')
    g.addColorStop(.6, 'rgba(91,6,4,.72)')
    g.addColorStop(1, 'rgba(68,4,3,0)')
    ctx.fillStyle = g
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
  }
  for (let i = 0; i < 45; i++) {
    const a = rng() * Math.PI * 2, d = size * (.16 + rng() * .34)
    ctx.fillStyle = `rgba(${55 + rng() * 40 | 0},3,2,${.3 + rng() * .55})`
    ctx.beginPath(); ctx.ellipse(cx + Math.cos(a) * d, cy + Math.sin(a) * d, 1 + rng() * 5, 1 + rng() * 10, a, 0, Math.PI * 2); ctx.fill()
  }
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createParticleTexture(hard = false, size = 64) {
  const [c, ctx] = canvas(size)
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  if (hard) {
    g.addColorStop(0, 'rgba(255,255,255,1)')
    g.addColorStop(.35, 'rgba(255,255,255,.95)')
    g.addColorStop(.7, 'rgba(255,255,255,.35)')
    g.addColorStop(1, 'rgba(255,255,255,0)')
  } else {
    g.addColorStop(0, 'rgba(255,255,255,.8)')
    g.addColorStop(.32, 'rgba(255,255,255,.42)')
    g.addColorStop(1, 'rgba(255,255,255,0)')
  }
  ctx.fillStyle = g; ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createGlowTexture(size = 256) {
  const [c, ctx] = canvas(size)
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(255,255,255,.9)')
  g.addColorStop(.12, 'rgba(255,229,181,.72)')
  g.addColorStop(.42, 'rgba(255,158,75,.16)')
  g.addColorStop(1, 'rgba(255,100,25,0)')
  ctx.fillStyle = g; ctx.fillRect(0, 0, size, size)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createRuneTexture(size = 512, color = '#ff6a35') {
  const [c, ctx] = canvas(size)
  ctx.clearRect(0, 0, size, size)
  const cx = size / 2, cy = size / 2
  ctx.strokeStyle = color
  ctx.lineWidth = 2
  ctx.globalAlpha = .8
  ctx.beginPath(); ctx.arc(cx, cy, size * .44, 0, Math.PI * 2); ctx.stroke()
  ctx.beginPath(); ctx.arc(cx, cy, size * .34, 0, Math.PI * 2); ctx.stroke()
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * Math.PI * 2
    ctx.save(); ctx.translate(cx, cy); ctx.rotate(a)
    ctx.beginPath(); ctx.moveTo(size * .35, 0); ctx.lineTo(size * .42, -6); ctx.lineTo(size * .42, 6); ctx.closePath(); ctx.stroke()
    ctx.restore()
  }
  ctx.font = `600 ${size * .07}px serif`
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
  ctx.globalAlpha = .65
  const runes = 'ᚠᚢᚦᚨᚱᚲᚷᚹᚺᚾᛁᛃ'
  for (let i = 0; i < 18; i++) {
    const a = i / 18 * Math.PI * 2
    ctx.save(); ctx.translate(cx + Math.cos(a) * size * .39, cy + Math.sin(a) * size * .39); ctx.rotate(a + Math.PI / 2); ctx.fillStyle = color; ctx.fillText(runes[i % runes.length], 0, 0); ctx.restore()
  }
  ctx.globalAlpha = 1
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

export function createCrackTexture(size = 512) {
  const [c, ctx] = canvas(size)
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, size, size)
  const rng = seededRandom(314)
  ctx.strokeStyle = '#fff'; ctx.shadowColor = '#fff'; ctx.shadowBlur = 5
  for (let i = 0; i < 18; i++) {
    ctx.beginPath(); let x = rng() * size, y = rng() * size; ctx.moveTo(x, y)
    for (let j = 0; j < 15; j++) { x += (rng() - .5) * 38; y += (rng() - .2) * 24; ctx.lineTo(x, y) }
    ctx.lineWidth = .4 + rng() * 2.2; ctx.stroke()
  }
  const tex = new THREE.CanvasTexture(c)
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  return tex
}

export function createDustTexture(size = 256) {
  const [c, ctx] = canvas(size)
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2)
  g.addColorStop(0, 'rgba(255,255,255,.6)')
  g.addColorStop(.5, 'rgba(255,255,255,.15)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = g; ctx.fillRect(0, 0, size, size)
  return new THREE.CanvasTexture(c)
}

import { clamp, rand } from './utils.js'

export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.sfxBus = null
    this.ambientBus = null
    this.volume = .75
    this.muted = false
    this.started = false
    this.intensity = 0
    this.nextBeat = 0
    this.nextCrowd = 0
    this.stepTimer = 0
  }

  start() {
    if (this.started) { this.ctx?.resume(); return }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.started = true
    const ctx = this.ctx
    this.master = ctx.createGain()
    this.master.gain.value = this.volume
    const comp = ctx.createDynamicsCompressor()
    comp.threshold.value = -18
    comp.knee.value = 18
    comp.ratio.value = 5
    comp.attack.value = .003
    comp.release.value = .2
    this.master.connect(comp)
    comp.connect(ctx.destination)
    this.sfxBus = ctx.createGain(); this.sfxBus.gain.value = .8; this.sfxBus.connect(this.master)
    this.ambientBus = ctx.createGain(); this.ambientBus.gain.value = .65; this.ambientBus.connect(this.master)
    this.noise = this.makeNoise(2, 'pink')
    this.white = this.makeNoise(1, 'white')
    this.buildAmbience()
    this.nextBeat = ctx.currentTime + 2
    this.nextCrowd = ctx.currentTime + 4
  }

  makeNoise(seconds, kind = 'white') {
    const ctx = this.ctx
    const length = Math.floor(ctx.sampleRate * seconds)
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate)
    const data = buffer.getChannelData(0)
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1
      if (kind === 'pink') {
        b0 = .99886 * b0 + white * .0555179
        b1 = .99332 * b1 + white * .0750759
        b2 = .96900 * b2 + white * .1538520
        b3 = .86650 * b3 + white * .3104856
        b4 = .55000 * b4 + white * .5329522
        b5 = -.7616 * b5 - white * .0168980
        data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * .5362) * .11
        b6 = white * .115926
      } else data[i] = white
    }
    return buffer
  }

  buildAmbience() {
    const ctx = this.ctx
    // Wind
    const wind = ctx.createBufferSource()
    wind.buffer = this.noise
    wind.loop = true
    const windFilter = ctx.createBiquadFilter()
    windFilter.type = 'lowpass'; windFilter.frequency.value = 260; windFilter.Q.value = .7
    const windGain = ctx.createGain(); windGain.gain.value = .032
    const lfo = ctx.createOscillator(); lfo.frequency.value = .065
    const lfoGain = ctx.createGain(); lfoGain.gain.value = .018
    lfo.connect(lfoGain); lfoGain.connect(windGain.gain)
    wind.connect(windFilter); windFilter.connect(windGain); windGain.connect(this.ambientBus)
    wind.start(); lfo.start()

    // Low cathedral drone
    for (const [f, gain] of [[41.2, .013], [61.7, .008], [82.4, .005]]) {
      const osc = ctx.createOscillator()
      osc.type = 'sine'; osc.frequency.value = f
      const g = ctx.createGain(); g.gain.value = gain
      const trem = ctx.createOscillator(); trem.frequency.value = .04 + Math.random() * .05
      const tg = ctx.createGain(); tg.gain.value = gain * .35
      trem.connect(tg); tg.connect(g.gain)
      osc.connect(g); g.connect(this.ambientBus); osc.start(); trem.start()
    }

    // Crowd bed
    const crowd = ctx.createBufferSource(); crowd.buffer = this.noise; crowd.loop = true
    const cf = ctx.createBiquadFilter(); cf.type = 'bandpass'; cf.frequency.value = 640; cf.Q.value = .45
    const cg = ctx.createGain(); cg.gain.value = .012
    const clfo = ctx.createOscillator(); clfo.frequency.value = .11
    const clg = ctx.createGain(); clg.gain.value = .007
    clfo.connect(clg); clg.connect(cg.gain)
    crowd.connect(cf); cf.connect(cg); cg.connect(this.ambientBus); crowd.start(); clfo.start()
    this.crowdGain = cg
  }

  setVolume(v) {
    this.volume = clamp(v, 0, 1)
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : this.volume, this.ctx.currentTime, .05)
  }

  setMuted(m) {
    this.muted = m
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : this.volume, this.ctx.currentTime, .04)
  }

  now() { return this.ctx?.currentTime || 0 }

  tone({ freq = 220, end = freq, duration = .25, gain = .1, type = 'sine', attack = .004, pan = 0, bus = null, lowpass = null }) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (end !== freq) osc.frequency.exponentialRampToValueAtTime(Math.max(1, end), t + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(.0001, t)
    g.gain.linearRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(.0001, t + duration)
    let node = osc
    if (lowpass) {
      const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = lowpass
      node.connect(f); node = f
    }
    const p = ctx.createStereoPanner(); p.pan.value = pan
    node.connect(g); g.connect(p); p.connect(bus || this.sfxBus)
    osc.start(t); osc.stop(t + duration + .04)
  }

  noiseBurst({ duration = .2, gain = .12, freq = 1200, endFreq = freq, q = 1, type = 'bandpass', pan = 0, attack = .002, bus = null }) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const src = ctx.createBufferSource(); src.buffer = this.white
    src.playbackRate.value = rand(.9, 1.1)
    const f = ctx.createBiquadFilter(); f.type = type; f.Q.value = q
    f.frequency.setValueAtTime(freq, t)
    if (endFreq !== freq) f.frequency.exponentialRampToValueAtTime(Math.max(30, endFreq), t + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(.0001, t)
    g.gain.linearRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(.0001, t + duration)
    const p = ctx.createStereoPanner(); p.pan.value = clamp(pan, -1, 1)
    src.connect(f); f.connect(g); g.connect(p); p.connect(bus || this.sfxBus)
    src.start(t); src.stop(t + duration + .03)
  }

  swing(power = 1) {
    if (!this.ctx) return
    this.noiseBurst({ duration: .18 + power * .1, gain: .11 * power, freq: 700, endFreq: 2200 + power * 900, q: 1.6, type: 'bandpass', attack: .045 })
    this.noiseBurst({ duration: .22, gain: .035, freq: 240, endFreq: 110, q: .7, type: 'lowpass' })
  }

  hit(power = 1, metal = false) {
    if (!this.ctx) return
    this.tone({ freq: 92 * power, end: 43, duration: .18 + power * .08, gain: .2 * power, type: 'sine' })
    this.tone({ freq: 156, end: 60, duration: .12, gain: .06, type: 'triangle' })
    this.noiseBurst({ duration: .12, gain: .15, freq: 480, endFreq: 180, q: .8, type: 'lowpass' })
    this.noiseBurst({ duration: .07, gain: .08, freq: 1800, endFreq: 600, q: .7 })
    if (metal) {
      for (const f of [1420, 2180, 3170]) this.tone({ freq: f, end: f * .98, duration: .28, gain: .035, type: 'sine' })
      this.noiseBurst({ duration: .14, gain: .08, freq: 4400, endFreq: 2400, q: 2 })
    }
  }

  block() {
    if (!this.ctx) return
    for (const f of [920, 1740, 2780, 4120]) this.tone({ freq: f, end: f * .96, duration: .32, gain: .045, type: 'sine' })
    this.noiseBurst({ duration: .18, gain: .12, freq: 3900, endFreq: 1400, q: 2.2 })
    this.tone({ freq: 72, end: 48, duration: .22, gain: .13, type: 'sine' })
  }

  parry() {
    if (!this.ctx) return
    for (const [f, g] of [[1240, .08], [2130, .06], [3290, .04], [4680, .02]]) this.tone({ freq: f, end: f * .985, duration: .62, gain: g, type: 'sine', attack: .002 })
    this.tone({ freq: 84, end: 38, duration: .5, gain: .17, type: 'sine' })
    this.noiseBurst({ duration: .18, gain: .12, freq: 5600, endFreq: 2200, q: 1.8 })
  }

  flesh(power = 1) {
    if (!this.ctx) return
    this.noiseBurst({ duration: .16, gain: .15, freq: 340, endFreq: 130, q: 1.1, type: 'lowpass' })
    this.noiseBurst({ duration: .07, gain: .07, freq: 1300, endFreq: 400, q: 3 })
    this.tone({ freq: 61, end: 34, duration: .28, gain: .11, type: 'sine' })
  }

  hurt() {
    if (!this.ctx) return
    this.tone({ freq: 110, end: 46, duration: .38, gain: .17, type: 'triangle' })
    this.noiseBurst({ duration: .2, gain: .1, freq: 340, endFreq: 90, q: .8, type: 'lowpass' })
    this.tone({ freq: 48, end: 36, duration: .75, gain: .08, type: 'sine' })
  }

  footstep(surface = 0) {
    if (!this.ctx) return
    this.noiseBurst({ duration: .09, gain: .038, freq: surface === 0 ? 240 : 530, endFreq: surface === 0 ? 90 : 160, q: 1.1, type: 'lowpass' })
    this.tone({ freq: surface === 0 ? 52 : 74, end: 36, duration: .1, gain: .035, type: 'sine' })
  }

  roar(boss = false) {
    if (!this.ctx) return
    const base = boss ? 74 : 126
    for (let i = 0; i < 3; i++) {
      this.tone({ freq: base * (1 + i * .03), end: base * .58, duration: boss ? 1.1 : .65, gain: .028, type: 'sawtooth', attack: .07, lowpass: 820 })
    }
    this.noiseBurst({ duration: boss ? 1.15 : .7, gain: .075, freq: 560, endFreq: 240, q: .7 })
    this.tone({ freq: base * .5, end: 31, duration: .9, gain: .08, type: 'sine' })
  }

  death() {
    if (!this.ctx) return
    this.tone({ freq: 130, end: 43, duration: .75, gain: .055, type: 'sawtooth', lowpass: 460 })
    this.flesh(1.2)
  }

  execute() {
    if (!this.ctx) return
    this.tone({ freq: 58, end: 24, duration: 1.8, gain: .2, type: 'sine', attack: .01 })
    this.tone({ freq: 146, end: 36, duration: 1.2, gain: .05, type: 'sawtooth', lowpass: 700 })
    this.noiseBurst({ duration: .8, gain: .1, freq: 1000, endFreq: 130, q: .65, type: 'lowpass', attack: .03 })
    this.ctx.suspend
  }

  heartbeat() {
    if (!this.ctx) return
    this.tone({ freq: 64, end: 38, duration: .22, gain: .11, type: 'sine', attack: .006 })
    setTimeout(() => this.tone({ freq: 58, end: 33, duration: .18, gain: .07, type: 'sine' }), 155)
  }

  ui(confirm = false) {
    if (!this.ctx) return
    this.tone({ freq: confirm ? 392 : 620, end: confirm ? 523 : 560, duration: confirm ? .24 : .09, gain: confirm ? .035 : .018, type: 'sine' })
    if (confirm) this.tone({ freq: 784, end: 1046, duration: .3, gain: .018, type: 'sine' })
  }

  unlock() {
    if (!this.ctx) return
    for (const [f, d] of [[392, .15], [523.25, .2], [659.25, .26], [1046.5, .8]]) this.tone({ freq: f, end: f * 1.002, duration: d, gain: .04, type: 'sine', attack: .01 })
  }

  waveHorn(boss = false) {
    if (!this.ctx) return
    const base = boss ? 82 : 110
    for (const [f, g] of [[base, .09], [base * 1.5, .045], [base * 2, .02]]) {
      this.tone({ freq: f, end: f * .99, duration: boss ? 2.2 : 1.4, gain: g, type: 'sawtooth', attack: .22, lowpass: 680 })
    }
    this.noiseBurst({ duration: 1.3, gain: .065, freq: 520, endFreq: 280, q: .5, type: 'lowpass', attack: .2 })
  }

  update(dt, intensity = 0, moving = false) {
    if (!this.ctx || this.ctx.state !== 'running') return
    this.intensity += (intensity - this.intensity) * Math.min(1, dt * .8)
    if (this.crowdGain) this.crowdGain.gain.setTargetAtTime(.012 + this.intensity * .018, this.ctx.currentTime, .8)
    if (this.ctx.currentTime > this.nextBeat) {
      if (this.intensity > .16) {
        const low = 48 + Math.random() * 12
        this.tone({ freq: low, end: 31, duration: .34, gain: .05 + this.intensity * .08, type: 'sine', bus: this.ambientBus })
        this.noiseBurst({ duration: .1, gain: .016 + this.intensity * .012, freq: 180, endFreq: 70, q: .7, type: 'lowpass', bus: this.ambientBus })
        if (this.intensity > .65) setTimeout(() => this.tone({ freq: low * .8, end: 28, duration: .28, gain: .045, type: 'sine', bus: this.ambientBus }), 230)
      }
      this.nextBeat = this.ctx.currentTime + Math.max(.48, 1.55 - this.intensity * .7) + Math.random() * .15
    }
    if (this.ctx.currentTime > this.nextCrowd) {
      if (this.intensity > .35 && Math.random() < .4) this.noiseBurst({ duration: .7, gain: .012, freq: 760 + Math.random() * 500, endFreq: 500, q: .9, bus: this.ambientBus })
      this.nextCrowd = this.ctx.currentTime + 3 + Math.random() * 4
    }
  }
}

