export function createEnvironmentMap(renderer) {
  const envScene = new THREE.Scene()
  const geo = new THREE.SphereGeometry(30, 24, 16)
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    uniforms: {
      top: { value: new THREE.Color(0x192535) },
      mid: { value: new THREE.Color(0x6f4a2d) },
      bottom: { value: new THREE.Color(0x160d08) }
    },
    vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `uniform vec3 top; uniform vec3 mid; uniform vec3 bottom; varying vec3 vP;
      void main(){ float h = normalize(vP).y * .5 + .5; vec3 c = mix(bottom, mid, smoothstep(.12,.52,h)); c = mix(c, top, smoothstep(.46,.96,h)); gl_FragColor = vec4(c, 1.); }`
  })
  envScene.add(new THREE.Mesh(geo, mat))
  const glowMat = new THREE.MeshBasicMaterial({ color: 0xffb76c })
  const glow1 = new THREE.Mesh(new THREE.SphereGeometry(1.8, 8, 8), glowMat)
  glow1.position.set(10, 2, -8); envScene.add(glow1)
  const glow2 = new THREE.Mesh(new THREE.SphereGeometry(1.2, 8, 8), new THREE.MeshBasicMaterial({ color: 0x527ca6 }))
  glow2.position.set(-9, 12, 4); envScene.add(glow2)
  const pmrem = new THREE.PMREMGenerator(renderer)
  const tex = pmrem.fromScene(envScene, .06).texture
  pmrem.dispose()
  geo.dispose(); mat.dispose(); glowMat.dispose(); glow1.geometry.dispose()
  return tex
}

function skyMaterial(theme) {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      topColor: { value: new THREE.Color(theme.skyTop) },
      bottomColor: { value: new THREE.Color(theme.skyBottom) },
      moonColor: { value: new THREE.Color(theme.moon) },
      moonPos: { value: new THREE.Vector3(.48, .24, -.83).normalize() },
      time: { value: 0 }
    },
    vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `
      varying vec3 vDir; uniform vec3 topColor; uniform vec3 bottomColor; uniform vec3 moonColor; uniform vec3 moonPos; uniform float time;
      float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
      float noise(vec2 p){ vec2 i=floor(p); vec2 f=fract(p); f=f*f*(3.-2.*f); return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y); }
      void main(){
        float h = clamp(vDir.y * .5 + .5, 0., 1.);
        vec3 col = mix(bottomColor, topColor, smoothstep(.22, .84, h));
        float md = max(0., dot(normalize(vDir), normalize(moonPos)));
        col += moonColor * pow(md, 220.) * 1.7;
        col += moonColor * pow(md, 18.) * .12;
        float cloud = 0.;
        vec2 uv = vDir.xz / max(.1, vDir.y + .45) * .55;
        for(int i=0;i<4;i++){ float n = noise(uv * (1.8 + float(i)*1.2) + vec2(time*.003, time*.001)); cloud += (n-.5) * (0.22 / (1. + float(i))); }
        col += moonColor * smoothstep(.08, .4, cloud) * smoothstep(.05, .35, h) * .07;
        float star = step(.9975, hash(floor(vDir.xz * 700. + vDir.y * 120.)));
        col += vec3(star) * smoothstep(.42, .85, h) * (1. - cloud) * .9;
        gl_FragColor = vec4(col, 1.);
      }`
  })
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene
    this.renderer = renderer
    this.group = null
    this.themeIndex = 0
    this.flames = []
    this.banners = []
    this.crowd = []
    this.hazards = []
    this.lights = []
    this.sky = null
    this.moon = null
    this.stars = null
    this.dust = null
    this.emberStream = null
    this.time = 0
    this.radius = 21.5
    this.crowdExcitement = 0
    this.arenaMoonDir = new THREE.Vector3(.48, .24, -.83).normalize()
  }

  build(themeIndex = 0, quality = 'auto') {
    this.themeIndex = themeIndex % ARENAS.length
    const theme = ARENAS[this.themeIndex]
    if (this.group) {
      this.scene.remove(this.group)
      this.disposeGroup(this.group)
    }
    this.group = new THREE.Group()
    this.group.name = 'arena'
    this.scene.add(this.group)
    this.flames = []
    this.banners = []
    this.crowd = []
    this.hazards = []
    this.lights = []
    this.quality = quality

    this.scene.fog = new THREE.FogExp2(theme.fog, theme.fogDensity)
    this.scene.background = new THREE.Color(theme.skyTop)
    this.buildSky(theme)
    this.buildLights(theme)
    this.buildGround(theme)
    this.buildWalls(theme)
    this.buildCrowd(theme)
    this.buildProps(theme)
    this.buildHazards(theme)
    this.buildAtmosphere(theme)
  }

  buildSky(theme) {
    if (this.sky) { this.scene.remove(this.sky); this.sky.material.dispose(); this.sky.geometry.dispose() }
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(170, 32, 20), skyMaterial(theme))
    this.sky.frustumCulled = false
    this.scene.add(this.sky)
    if (this.stars) { this.scene.remove(this.stars); this.stars.geometry.dispose(); this.stars.material.dispose() }
    const starGeo = new THREE.BufferGeometry()
    const positions = []
    for (let i = 0; i < 900; i++) {
      const v = new THREE.Vector3(rand(-1, 1), rand(.05, 1), rand(-1, 1)).normalize().multiplyScalar(140)
      positions.push(v.x, v.y, v.z)
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    this.stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xcfd7d8, size: .22, transparent: true, opacity: .52, depthWrite: false, sizeAttenuation: true }))
    this.scene.add(this.stars)
    if (this.moon) { this.scene.remove(this.moon); this.moon.material.map?.dispose(); this.moon.material.dispose() }
    const moonMat = new THREE.SpriteMaterial({ map: createGlowTexture(256), color: theme.moon, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .9 })
    this.moon = new THREE.Sprite(moonMat)
    this.moon.position.copy(this.arenaMoonDir).multiplyScalar(120)
    this.moon.scale.setScalar(42)
    this.scene.add(this.moon)
  }

  buildLights(theme) {
    const hemi = new THREE.HemisphereLight(theme.ambient, 0x0c0806, 1.55)
    this.group.add(hemi); this.lights.push(hemi)
    const sun = new THREE.DirectionalLight(theme.sun, 2.3)
    sun.position.set(-24, 38, -26)
    sun.castShadow = true
    sun.shadow.mapSize.set(this.quality === 'low' ? 1024 : 2048, this.quality === 'low' ? 1024 : 2048)
    sun.shadow.camera.near = 5
    sun.shadow.camera.far = 80
    sun.shadow.camera.left = -27
    sun.shadow.camera.right = 27
    sun.shadow.camera.top = 27
    sun.shadow.camera.bottom = -27
    sun.shadow.bias = -.0008
    sun.shadow.normalBias = .025
    this.group.add(sun); this.lights.push(sun)
    this.sun = sun
    const fill = new THREE.DirectionalLight(theme.torch, .28)
    fill.position.set(12, 5, 18)
    this.group.add(fill); this.lights.push(fill)
    const center = new THREE.PointLight(theme.torch, 1.2, 23, 2)
    center.position.set(0, 7, -7)
    this.group.add(center); this.lights.push(center)
    this.centerLight = center
  }

  buildGround(theme) {
    let map, bump, emissiveMap = null, roughness = .96
    if (theme.ground === 'sand') { map = createSandTexture(512); map.repeat.set(4.5, 4.5); bump = map; }
    else if (theme.ground === 'basalt') { map = createBasaltTexture(512); map.repeat.set(3.4, 3.4); bump = map; emissiveMap = createLavaGlowTexture(512); emissiveMap.repeat.set(3.4, 3.4); roughness = .82 }
    else { map = createStoneTexture(1, 512); map.repeat.set(4, 4); bump = createCrackTexture(512); bump.repeat.set(4, 4) }
    const mat = new THREE.MeshStandardMaterial({
      map, bumpMap: bump, bumpScale: .07, roughness, metalness: .04,
      color: theme.ground === 'sand' ? 0x9e8260 : theme.ground === 'basalt' ? 0x5b4942 : 0x73746e
    })
    if (theme.ground === 'basalt') {
      mat.emissive = new THREE.Color(0xd64a1a)
      mat.emissiveMap = emissiveMap
      mat.emissiveIntensity = .7
    }
    const ground = new THREE.Mesh(new THREE.CircleGeometry(26.2, 96), mat)
    ground.rotation.x = -Math.PI / 2
    ground.receiveShadow = true
    this.group.add(ground)
    this.ground = ground
    // dark outer ring
    const outer = new THREE.Mesh(new THREE.RingGeometry(25.8, 30, 96), new THREE.MeshStandardMaterial({ color: 0x171310, roughness: .98, metalness: .02 }))
    outer.rotation.x = -Math.PI / 2; outer.position.y = .003; this.group.add(outer)

    // central sigil
    const runeTex = createRuneTexture(512, theme.ground === 'basalt' ? '#ff5a2b' : theme.ground === 'stone' ? '#6bd3b2' : '#b68b50')
    const sigil = new THREE.Mesh(new THREE.PlaneGeometry(11, 11), new THREE.MeshBasicMaterial({ map: runeTex, transparent: true, opacity: .28, depthWrite: false, blending: THREE.AdditiveBlending, color: theme.ground === 'basalt' ? 0xff6038 : theme.ground === 'stone' ? 0x5db695 : 0xc99b5d }))
    sigil.rotation.x = -Math.PI / 2; sigil.position.y = .012; this.group.add(sigil)
    this.sigil = sigil
    const ring = new THREE.Mesh(new THREE.TorusGeometry(5.75, .04, 6, 96), new THREE.MeshStandardMaterial({ color: 0x4c3a26, metalness: .6, roughness: .4 }))
    ring.rotation.x = Math.PI / 2; ring.position.y = .025; this.group.add(ring)

    // scattered bones and skulls
    const boneMat = new THREE.MeshStandardMaterial({ color: 0x968872, roughness: .86 })
    const skullGeo = new THREE.SphereGeometry(.12, 7, 5)
    const boneGeo = new THREE.CylinderGeometry(.018, .022, .34, 5)
    const rng = seededRandom(48)
    for (let i = 0; i < 55; i++) {
      const a = rng() * Math.PI * 2
      const r = 8 + rng() * 16.5
      const g = rng() > .38 ? new THREE.Mesh(boneGeo, boneMat) : new THREE.Mesh(skullGeo, boneMat)
      if (g.geometry === skullGeo) g.scale.set(1, .82, 1)
      g.position.set(Math.cos(a) * r, .03 + rng() * .015, Math.sin(a) * r)
      g.rotation.set(Math.PI / 2 + rand(-.3, .3), rand(0, 6), rand(-.3, .3))
      g.castShadow = true
      this.group.add(g)
    }
  }

  buildWalls(theme) {
    const stoneMap = createStoneTexture(2, 512); stoneMap.repeat.set(8, 2)
    const wallMat = new THREE.MeshStandardMaterial({ map: stoneMap, bumpMap: stoneMap, bumpScale: .12, color: theme.ground === 'stone' ? 0x6e726d : theme.ground === 'basalt' ? 0x4b3731 : 0x8a765e, roughness: .93, side: THREE.DoubleSide })
    const wall = new THREE.Mesh(new THREE.CylinderGeometry(25.4, 26.1, 4.7, 80, 1, true), wallMat)
    wall.position.y = 2.35
    wall.receiveShadow = true; wall.castShadow = true
    this.group.add(wall)
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x393029, roughness: .8, metalness: .18 })
    for (const [y, r, h] of [[.45, 25.45, .3], [4.55, 25.2, .32], [2.25, 25.35, .11]]) {
      const trim = new THREE.Mesh(new THREE.CylinderGeometry(r, r, h, 80, 1, true), trimMat)
      trim.position.y = y; trim.receiveShadow = true; this.group.add(trim)
    }
    // arch niches
    const nicheMat = new THREE.MeshStandardMaterial({ color: 0x0d0a08, roughness: 1 })
    for (let i = 0; i < 10; i++) {
      const a = (i / 10) * Math.PI * 2 + .31
      if (Math.abs(((a + Math.PI) % (Math.PI * 2)) - Math.PI) < .35) continue
      const arch = new THREE.Group()
      const dark = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 3.2), nicheMat)
      dark.position.z = -.04; arch.add(dark)
      const top = new THREE.Mesh(new THREE.CircleGeometry(1.1, 20, 0, Math.PI), nicheMat)
      top.position.set(0, 1.6, -.035); arch.add(top)
      const rim = new THREE.Mesh(new THREE.TorusGeometry(1.16, .08, 5, 18, Math.PI), trimMat)
      rim.position.set(0, 1.58, 0); arch.add(rim)
      arch.position.set(Math.sin(a) * 25.05, 2.5, Math.cos(a) * 25.05)
      arch.lookAt(0, 2.5, 0)
      this.group.add(arch)
    }

    // grand gate at north
    const gate = new THREE.Group()
    const gateMat = new THREE.MeshStandardMaterial({ color: 0x2c2520, roughness: .84, metalness: .26 })
    const gateWood = new THREE.MeshStandardMaterial({ color: 0x22150f, roughness: .95 })
    for (const x of [-4.7, 4.7]) {
      const tower = new THREE.Mesh(new THREE.BoxGeometry(2.2, 8, 2.2), gateMat)
      tower.position.set(x, 4, 0); tower.castShadow = true; tower.receiveShadow = true; gate.add(tower)
      const cap = new THREE.Mesh(new THREE.ConeGeometry(1.7, 1.8, 4), gateMat)
      cap.position.set(x, 8.8, 0); cap.rotation.y = Math.PI / 4; gate.add(cap)
    }
    const lintel = new THREE.Mesh(new THREE.BoxGeometry(11.4, 1.25, 2.1), gateMat)
    lintel.position.y = 7.35; lintel.castShadow = true; gate.add(lintel)
    const archShape = new THREE.Shape()
    archShape.moveTo(-4.1, 0); archShape.lineTo(-4.1, 4.3); archShape.absarc(0, 4.3, 4.1, Math.PI, 0, true); archShape.lineTo(4.1, 0); archShape.closePath()
    const doorMat = new THREE.MeshStandardMaterial({ color: 0x0b0806, roughness: 1 })
    const door = new THREE.Mesh(new THREE.ShapeGeometry(archShape, 24), doorMat)
    door.position.set(0, 0, -.05); gate.add(door)
    for (let i = -3; i <= 3; i++) {
      const bar = new THREE.Mesh(new THREE.CylinderGeometry(.045, .055, 6.8, 6), new THREE.MeshStandardMaterial({ color: 0x3b3b37, metalness: .8, roughness: .34 }))
      bar.position.set(i * .88, 3.4, .2); gate.add(bar)
      const spike = new THREE.Mesh(new THREE.ConeGeometry(.075, .3, 4), bar.material)
      spike.position.set(i * .88, 0, .2); spike.rotation.x = Math.PI; gate.add(spike)
    }
    const skull = new THREE.Mesh(new THREE.SphereGeometry(.28, 8, 6), new THREE.MeshStandardMaterial({ color: 0xa09278, roughness: .9 }))
    skull.scale.set(1, 1.2, .9); skull.position.set(0, 8.55, .9); gate.add(skull)
    const gateRing = new THREE.Mesh(new THREE.TorusGeometry(.13, .035, 5, 12), gateMat)
    gateRing.position.set(0, 8.55, 1.15); gate.add(gateRing)
    gate.position.set(0, 0, -25.1)
    this.group.add(gate)
    this.gate = gate

    // banners
    const bannerTex = createBannerTexture(theme.banner, 512)
    for (let i = 0; i < 8; i++) {
      if (i === 1 || i === 6) continue
      const a = i / 8 * Math.PI * 2 + Math.PI
      const banner = new THREE.Group()
      const cloth = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 4.1, 5, 8), new THREE.MeshStandardMaterial({ map: bannerTex, transparent: true, side: THREE.DoubleSide, roughness: .98, metalness: 0, color: 0xd0c2aa }))
      cloth.position.y = -2; cloth.castShadow = true
      const rod = new THREE.Mesh(new THREE.CylinderGeometry(.045, .045, 1.9, 8), new THREE.MeshStandardMaterial({ color: 0x4a4032, metalness: .7, roughness: .4 }))
      rod.rotation.z = Math.PI / 2; rod.position.y = .04; banner.add(rod)
      banner.add(cloth)
      banner.position.set(Math.sin(a) * 24.9, 4.6, Math.cos(a) * 24.9)
      banner.lookAt(0, 4.6, 0)
      this.group.add(banner)
      this.banners.push({ group: banner, cloth, phase: rand(0, 6), base: cloth.geometry.attributes.position.array.slice() })
    }

    // pillars and braziers
    const columnMat = new THREE.MeshStandardMaterial({ map: stoneMap, color: theme.ground === 'basalt' ? 0x5b4741 : 0x88745d, roughness: .9 })
    const bronze = new THREE.MeshStandardMaterial({ color: 0x4e3e28, metalness: .72, roughness: .44 })
    for (let i = 0; i < 8; i++) {
      const a = i / 8 * Math.PI * 2
      if (i === 2) continue
      const r = 21.6
      const x = Math.sin(a) * r, z = Math.cos(a) * r
      const col = new THREE.Group()
      const base = new THREE.Mesh(new THREE.CylinderGeometry(.62, .76, .5, 8), columnMat); base.position.y = .25; col.add(base)
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(.33, .45, 4.5, 10), columnMat); shaft.position.y = 2.7; shaft.castShadow = true; shaft.receiveShadow = true; col.add(shaft)
      const capital = new THREE.Mesh(new THREE.CylinderGeometry(.62, .38, .42, 8), columnMat); capital.position.y = 5.12; col.add(capital)
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(.52, .27, .36, 10), bronze); bowl.position.y = 5.5; col.add(bowl)
      const rim = new THREE.Mesh(new THREE.TorusGeometry(.51, .05, 5, 16), bronze); rim.rotation.x = Math.PI / 2; rim.position.y = 5.67; col.add(rim)
      col.position.set(x, 0, z)
      col.rotation.y = -a
      this.group.add(col)
      this.addFlame(x, 5.75, z, 1.0 + (i % 3) * .18, theme, i < 4)
    }

    // wall torches
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2 + .32
      const x = Math.sin(a) * 24.6, z = Math.cos(a) * 24.6
      this.addFlame(x, 4.15, z, .62, theme, false)
      const bracket = new THREE.Mesh(new THREE.CylinderGeometry(.035, .035, .8, 6), bronze)
      bracket.position.set(x * .98, 3.7, z * .98); bracket.rotation.x = .3; this.group.add(bracket)
    }
  }

  addFlame(x, y, z, scale, theme, light = false) {
    const glowMat = new THREE.SpriteMaterial({ map: createGlowTexture(128), color: theme.torch, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .92 })
    const sprite = new THREE.Sprite(glowMat)
    sprite.position.set(x, y, z)
    sprite.scale.setScalar(.9 * scale)
    this.group.add(sprite)
    const core = new THREE.Sprite(new THREE.SpriteMaterial({ map: createGlowTexture(128), color: 0xffdf9c, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: .86 }))
    core.position.set(x, y + .05, z); core.scale.setScalar(.4 * scale); this.group.add(core)
    let point = null
    if (light) {
      point = new THREE.PointLight(theme.torch, 5.3 * scale, 12, 2)
      point.position.set(x, y + .25, z)
      this.group.add(point)
      this.lights.push(point)
    }
    this.flames.push({ sprite, core, point, baseY: y, scale, phase: rand(0, 10), rate: rand(.8, 1.4) })
  }

  buildCrowd(theme) {
    const count = this.quality === 'low' ? 160 : 280
    const bodyGeo = new THREE.CapsuleGeometry(.12, .32, 2, 5)
    const headGeo = new THREE.SphereGeometry(.1, 6, 5)
    const bodyMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .98, metalness: 0 })
    const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .92 })
    const bodies = new THREE.InstancedMesh(bodyGeo, bodyMat, count)
    const heads = new THREE.InstancedMesh(headGeo, headMat, count)
    bodies.castShadow = false; bodies.receiveShadow = false
    heads.castShadow = false; heads.receiveShadow = false
    const matrix = new THREE.Matrix4(), quat = new THREE.Quaternion(), pos = new THREE.Vector3(), scl = new THREE.Vector3()
    const colors = [0x27130f, 0x31251d, 0x1c1a17, 0x3a1a13, 0x2c2a24, 0x231c18]
    for (let i = 0; i < count; i++) {
      const row = i % 4
      const a = Math.random() * Math.PI * 2
      const r = 27.6 + row * 2.1 + rand(-.4, .4)
      const y = 2.55 + row * .55
      const s = rand(.8, 1.15)
      pos.set(Math.sin(a) * r, y, Math.cos(a) * r)
      quat.setFromEuler(new THREE.Euler(0, Math.atan2(-Math.sin(a), -Math.cos(a)), 0))
      scl.set(s, s, s)
      matrix.compose(pos, quat, scl)
      bodies.setMatrixAt(i, matrix)
      bodies.setColorAt(i, new THREE.Color(pick(colors)))
      pos.y += .39 * s
      matrix.compose(pos, quat, scl)
      heads.setMatrixAt(i, matrix)
      heads.setColorAt(i, new THREE.Color(Math.random() < .5 ? 0x6e513d : 0x8b6950))
      this.crowd.push({ angle: a, radius: r, baseY: y, scale: s, phase: rand(0, Math.PI * 2) })
    }
    bodies.instanceMatrix.needsUpdate = true
    heads.instanceMatrix.needsUpdate = true
    if (bodies.instanceColor) bodies.instanceColor.needsUpdate = true
    if (heads.instanceColor) heads.instanceColor.needsUpdate = true
    this.group.add(bodies, heads)
    this.crowdBodies = bodies
    this.crowdHeads = heads
    this.crowdMatrix = matrix
    this.crowdQuat = quat
    this.crowdPos = pos
    this.crowdScl = scl
  }

  buildProps(theme) {
    const wood = new THREE.MeshStandardMaterial({ color: 0x2d1c12, roughness: .97 })
    const iron = new THREE.MeshStandardMaterial({ color: 0x312f2a, metalness: .64, roughness: .5 })
    if (this.themeIndex === 1) {
      // gallows
      for (let i = 0; i < 3; i++) {
        const a = 2.1 + i * .67
        const r = 18.2
        const g = new THREE.Group()
        const post = new THREE.Mesh(new THREE.CylinderGeometry(.13, .17, 5.6, 6), wood)
        post.position.y = 2.8; g.add(post)
        const arm = new THREE.Mesh(new THREE.BoxGeometry(2.4, .2, .2), wood)
        arm.position.set(1.1, 5.3, 0); g.add(arm)
        const rope = new THREE.Mesh(new THREE.CylinderGeometry(.015, .015, 1.4, 4), new THREE.MeshStandardMaterial({ color: 0x6c5940, roughness: 1 }))
        rope.position.set(1.8, 4.55, 0); g.add(rope)
        const noose = new THREE.Mesh(new THREE.TorusGeometry(.12, .018, 4, 10), rope.material)
        noose.position.set(1.8, 3.83, 0); g.add(noose)
        g.position.set(Math.sin(a) * r, 0, Math.cos(a) * r)
        g.rotation.y = -a
        this.group.add(g)
      }
      // hanging cage
      const cage = new THREE.Group()
      for (let i = 0; i < 8; i++) {
        const bar = new THREE.Mesh(new THREE.CylinderGeometry(.025, .025, 1.8, 4), iron)
        const a = i / 8 * Math.PI * 2
        bar.position.set(Math.cos(a) * .5, 0, Math.sin(a) * .5); cage.add(bar)
      }
      const top = new THREE.Mesh(new THREE.TorusGeometry(.5, .035, 4, 12), iron); top.rotation.x = Math.PI / 2; top.position.y = .9; cage.add(top)
      const bottom = top.clone(); bottom.position.y = -.9; cage.add(bottom)
      const chain = new THREE.Mesh(new THREE.CylinderGeometry(.02, .02, 3, 4), iron); chain.position.y = 2.9; cage.add(chain)
      cage.position.set(-7, 5.2, -19); this.group.add(cage)
      this.hangingCage = cage
    }
    if (this.themeIndex === 2) {
      // jagged obsidian fangs
      const obMat = new THREE.MeshStandardMaterial({ color: 0x1d1414, metalness: .32, roughness: .52 })
      for (let i = 0; i < 9; i++) {
        const a = rand(0, Math.PI * 2), r = rand(18.5, 22.5)
        const h = rand(1.1, 3.4)
        const spike = new THREE.Mesh(new THREE.ConeGeometry(rand(.18, .48), h, 5), obMat)
        spike.position.set(Math.sin(a) * r, h / 2, Math.cos(a) * r)
        spike.rotation.z = rand(-.18, .18)
        this.group.add(spike)
      }
      // lava cracks lights
      for (let i = 0; i < 4; i++) {
        const a = i / 4 * Math.PI * 2 + .5
        const light = new THREE.PointLight(0xff3b12, 2.2, 9, 2)
        light.position.set(Math.sin(a) * 13, .35, Math.cos(a) * 13)
        this.group.add(light); this.lights.push(light)
      }
    }
    // chains along the wall
    const chainMat = new THREE.MeshStandardMaterial({ color: 0x272521, metalness: .8, roughness: .45 })
    for (let c = 0; c < 4; c++) {
      const a = c * 1.55 + .4
      const x = Math.sin(a) * 24.7, z = Math.cos(a) * 24.7
      for (let i = 0; i < 12; i++) {
        const link = new THREE.Mesh(new THREE.TorusGeometry(.06, .018, 3, 6), chainMat)
        link.position.set(x, 5.1 - i * .11, z)
        link.rotation.set(i % 2 ? 0 : Math.PI / 2, rand(0, 3), 0)
        this.group.add(link)
      }
    }
  }

  buildHazards(theme) {
    const positions = [
      { x: -8.5, z: 2.5 }, { x: 8.5, z: 2.5 }, { x: -7.5, z: -10.5 }, { x: 7.5, z: -10.5 }
    ]
    const runeTex = createRuneTexture(256, theme.ground === 'basalt' ? '#ff6a35' : theme.ground === 'stone' ? '#74dcb8' : '#c79555')
    for (const p of positions) {
      const group = new THREE.Group()
      const base = new THREE.Mesh(new THREE.CylinderGeometry(1.45, 1.54, .07, 32), new THREE.MeshStandardMaterial({ color: 0x2a2722, metalness: .45, roughness: .65 }))
      base.position.y = .035; base.receiveShadow = true; group.add(base)
      const rune = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 2.4), new THREE.MeshBasicMaterial({ map: runeTex, transparent: true, opacity: .34, depthWrite: false, blending: THREE.AdditiveBlending, color: theme.ground === 'stone' ? 0x73d4b0 : 0xff6b3b }))
      rune.rotation.x = -Math.PI / 2; rune.position.y = .075; group.add(rune)
      const spikeGeo = new THREE.ConeGeometry(.1, 1.1, 5)
      const spikeMat = new THREE.MeshStandardMaterial({ color: 0x77766c, metalness: .85, roughness: .3 })
      const spikes = new THREE.InstancedMesh(spikeGeo, spikeMat, 14)
      spikes.castShadow = true
      const matrix = new THREE.Matrix4()
      const spikeData = []
      for (let i = 0; i < 14; i++) {
        const a = i / 14 * Math.PI * 2
        const r = i < 7 ? .5 : .95
        spikeData.push({ x: Math.cos(a) * r, z: Math.sin(a) * r, s: rand(.7, 1.2) })
      }
      for (let i = 0; i < 14; i++) {
        matrix.makeScale(1, .02, 1)
        matrix.setPosition(spikeData[i].x, 0, spikeData[i].z)
        spikes.setMatrixAt(i, matrix)
      }
      group.add(spikes)
      group.position.set(p.x, 0, p.z)
      this.group.add(group)
      this.hazards.push({ group, spikes, rune, base, phase: rand(0, 5), cycle: 4.4, active: false, spikeData, matrix, position: new THREE.Vector3(p.x, 0, p.z), wasActive: false })
    }
  }

  buildAtmosphere(theme) {
    const dustCount = this.quality === 'low' ? 180 : 360
    const geo = new THREE.BufferGeometry()
    const positions = new Float32Array(dustCount * 3)
    const phases = new Float32Array(dustCount)
    for (let i = 0; i < dustCount; i++) {
      positions[i * 3] = rand(-24, 24)
      positions[i * 3 + 1] = rand(.2, 10)
      positions[i * 3 + 2] = rand(-24, 24)
      phases[i] = rand(0, Math.PI * 2)
    }
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const tex = createDustTexture(64)
    const mat = new THREE.PointsMaterial({ color: theme.ground === 'basalt' ? 0xff6b3a : theme.ground === 'stone' ? 0x92b9aa : 0xd8b887, size: .055, map: tex, transparent: true, opacity: .55, depthWrite: false, blending: THREE.AdditiveBlending })
    this.dust = new THREE.Points(geo, mat)
    this.group.add(this.dust)
    this.dustData = { positions, phases, count: dustCount }

    // embers rising near fire
    const emberCount = this.quality === 'low' ? 80 : 160
    const eg = new THREE.BufferGeometry()
    const ep = new Float32Array(emberCount * 3)
    const esp = new Float32Array(emberCount * 3)
    for (let i = 0; i < emberCount; i++) {
      const a = rand(0, 6.28), r = rand(7, 23)
      ep[i * 3] = Math.sin(a) * r
      ep[i * 3 + 1] = rand(0, 12)
      ep[i * 3 + 2] = Math.cos(a) * r
      esp[i * 3] = rand(-.15, .15); esp[i * 3 + 1] = rand(.35, 1.2); esp[i * 3 + 2] = rand(-.15, .15)
    }
    eg.setAttribute('position', new THREE.BufferAttribute(ep, 3))
    this.emberStream = new THREE.Points(eg, new THREE.PointsMaterial({ color: theme.torch, size: .08, map: createDustTexture(32), transparent: true, opacity: .8, blending: THREE.AdditiveBlending, depthWrite: false }))
    this.group.add(this.emberStream)
    this.emberData = { positions: ep, speed: esp, count: emberCount }
  }

  update(dt, intensity = 0) {
    this.time += dt
    this.crowdExcitement += (intensity - this.crowdExcitement) * Math.min(1, dt * 1.5)
    const time = this.time
    if (this.sky) this.sky.material.uniforms.time.value = time
    // flames
    for (const f of this.flames) {
      const flicker = .82 + Math.sin(time * 12 * f.rate + f.phase) * .1 + Math.sin(time * 19.7 + f.phase * 2) * .07
      f.sprite.scale.setScalar(.92 * f.scale * flicker)
      f.core.scale.setScalar(.48 * f.scale * (0.9 + Math.sin(time * 16 + f.phase) * .12))
      f.core.position.y = f.baseY + .06 + Math.sin(time * 9 + f.phase) * .04
      f.sprite.position.y = f.baseY + Math.sin(time * 7 + f.phase) * .03
      if (f.point) f.point.intensity = (4.8 + Math.sin(time * 15 + f.phase) * .7) * f.scale
    }
    // crowd idle
    if (this.crowdBodies) {
      const m = this.crowdMatrix, q = this.crowdQuat, p = this.crowdPos, s = this.crowdScl
      const count = this.crowd.length
      for (let i = 0; i < count; i++) {
        const c = this.crowd[i]
        const bob = Math.sin(time * (1.2 + this.crowdExcitement * 3.2) + c.phase) * (.012 + this.crowdExcitement * .07)
        const sway = Math.sin(time * .4 + c.phase) * .04
        p.set(Math.sin(c.angle + sway * .02) * c.radius, c.baseY + bob, Math.cos(c.angle + sway * .02) * c.radius)
        q.setFromEuler(new THREE.Euler(0, Math.atan2(-Math.sin(c.angle), -Math.cos(c.angle)), 0))
        s.set(c.scale, c.scale, c.scale)
        m.compose(p, q, s)
        this.crowdBodies.setMatrixAt(i, m)
        p.y += .39 * c.scale + bob * .6
        m.compose(p, q, s)
        this.crowdHeads.setMatrixAt(i, m)
      }
      this.crowdBodies.instanceMatrix.needsUpdate = true
      this.crowdHeads.instanceMatrix.needsUpdate = true
    }
    // banners
    for (const b of this.banners) {
      const posAttr = b.cloth.geometry.attributes.position
      const base = b.base
      for (let i = 0; i < posAttr.count; i++) {
        const x = base[i * 3], y = base[i * 3 + 1]
        const wave = Math.sin(time * 1.4 + b.phase + y * .8 + x * 1.2) * .08 * (1 - (y + 2) / 4.2)
        posAttr.setZ(i, wave)
      }
      posAttr.needsUpdate = true
    }
    // hazards
    for (const h of this.hazards) {
      h.phase += dt
      const cyc = h.phase % 6
      const warn = cyc > 3.75 && cyc < 4.55
      const active = cyc >= 4.55 && cyc < 5.55
      h.active = active
      h.rune.material.opacity = warn ? .38 + Math.sin(time * 18) * .2 : active ? .16 : .18
      const rise = active ? Math.min(1, (cyc - 4.55) * 7) : Math.max(0, 1 - (cyc - 5.55) * 9)
      for (let i = 0; i < h.spikeData.length; i++) {
        const d = h.spikeData[i]
        h.matrix.makeScale(1, Math.max(.02, rise * d.s), 1)
        h.matrix.setPosition(d.x, .04 + rise * .42, d.z)
        h.spikes.setMatrixAt(i, h.matrix)
      }
      h.spikes.instanceMatrix.needsUpdate = true
    }
    // dust drift
    if (this.dust) {
      const a = this.dust.geometry.attributes.position
      for (let i = 0; i < this.dustData.count; i++) {
        let y = a.getY(i) + dt * (.08 + (i % 5) * .02)
        let x = a.getX(i) + Math.sin(time * .3 + this.dustData.phases[i]) * dt * .08
        let z = a.getZ(i) + Math.cos(time * .24 + this.dustData.phases[i]) * dt * .06
        if (y > 10) y = .2
        if (x > 24) x = -24; if (x < -24) x = 24
        if (z > 24) z = -24; if (z < -24) z = 24
        a.setXYZ(i, x, y, z)
      }
      a.needsUpdate = true
    }
    // embers
    if (this.emberStream) {
      const a = this.emberStream.geometry.attributes.position
      const { speed, count } = this.emberData
      for (let i = 0; i < count; i++) {
        let y = a.getY(i) + dt * speed[i * 3 + 1]
        let x = a.getX(i) + Math.sin(time + i) * dt * .08
        let z = a.getZ(i) + Math.cos(time * .7 + i) * dt * .06
        if (y > 13) { y = 0; x = rand(-23, 23); z = rand(-23, 23) }
        a.setXYZ(i, x, y, z)
      }
      a.needsUpdate = true
    }
    if (this.hangingCage) {
      this.hangingCage.rotation.z = Math.sin(time * .55) * .035
    }
    if (this.centerLight) this.centerLight.intensity = 1.1 + this.crowdExcitement * 1.4
    if (this.sigil) this.sigil.material.opacity = .22 + Math.sin(time * .8) * .04 + this.crowdExcitement * .05
  }

  excite(amount = .4) {
    this.crowdExcitement = Math.min(1, this.crowdExcitement + amount)
  }

  clampToArena(pos, padding = .45) {
    const r = Math.hypot(pos.x, pos.z)
    const max = this.radius - padding
    if (r > max) {
      pos.x = (pos.x / r) * max
      pos.z = (pos.z / r) * max
    }
    return pos
  }

  distanceToEdge(pos) {
    return this.radius - Math.hypot(pos.x, pos.z)
  }

  disposeGroup(group) {
    group.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose()
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material]
        for (const m of mats) {
          for (const k of ['map', 'bumpMap', 'emissiveMap', 'normalMap']) if (m[k]) m[k].dispose()
          m.dispose()
        }
      }
    })
  }

  dispose() {
    if (this.group) { this.scene.remove(this.group); this.disposeGroup(this.group) }
    if (this.sky) { this.scene.remove(this.sky); this.sky.geometry.dispose(); this.sky.material.dispose() }
    if (this.stars) { this.scene.remove(this.stars); this.stars.geometry.dispose(); this.stars.material.dispose() }
    if (this.moon) { this.scene.remove(this.moon); this.moon.material.map?.dispose(); this.moon.material.dispose() }
  }
}

import * as THREE from 'three'
import { rand, clamp, pick } from './utils.js'
import { createParticleTexture, createBloodSplatTexture, createGlowTexture } from './textures.js'

const pointVertex = `
attribute float aSize;
attribute float aAlpha;
attribute vec3 aColor;
varying float vAlpha;
varying vec3 vColor;
void main() {
  vAlpha = aAlpha;
  vColor = aColor;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
  gl_Position = projectionMatrix * mv;
}`
const pointFragment = `
uniform sampler2D uMap;
varying float vAlpha;
varying vec3 vColor;
void main() {
  vec4 tex = texture2D(uMap, gl_PointCoord);
  if (tex.a * vAlpha < .01) discard;
  gl_FragColor = vec4(vColor, tex.a * vAlpha);
}`

class ParticlePool {
  constructor(scene, max, additive, texture, color) {
    this.max = max
    this.particles = []
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    this.geo = new THREE.BufferGeometry()
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    this.geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3))
    this.geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1))
    this.geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    this.geo.setDrawRange(0, 0)
    this.mat = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: texture } },
      vertexShader: pointVertex,
      fragmentShader: pointFragment,
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      vertexColors: false
    })
    this.points = new THREE.Points(this.geo, this.mat)
    this.points.frustumCulled = false
    scene.add(this.points)
    this.color = color
  }

  spawn(position, velocity, opts = {}) {
    if (this.particles.length >= this.max) this.particles.shift()
    this.particles.push({
      x: position.x, y: position.y, z: position.z,
      vx: velocity.x, vy: velocity.y, vz: velocity.z,
      gravity: opts.gravity ?? -9,
      drag: opts.drag ?? 1.2,
      life: opts.life ?? .8,
      maxLife: opts.life ?? .8,
      size: opts.size ?? .08,
      color: new THREE.Color(opts.color ?? this.color),
      fade: opts.fade ?? 1,
      floor: opts.floor ?? 0
    })
  }

  update(dt) {
    let n = 0
    const arr = this.particles
    for (let i = arr.length - 1; i >= 0; i--) {
      const p = arr[i]
      p.life -= dt
      if (p.life <= 0) { arr.splice(i, 1); continue }
      p.vy += p.gravity * dt
      const damp = Math.max(0, 1 - p.drag * dt)
      p.vx *= damp; p.vz *= damp
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt
      if (p.y < p.floor + .02) { p.y = p.floor + .02; p.vy = Math.abs(p.vy) * .25; p.vx *= .62; p.vz *= .62 }
      const t = p.life / p.maxLife
      this.positions[n * 3] = p.x
      this.positions[n * 3 + 1] = p.y
      this.positions[n * 3 + 2] = p.z
      this.colors[n * 3] = p.color.r
      this.colors[n * 3 + 1] = p.color.g
      this.colors[n * 3 + 2] = p.color.b
      this.sizes[n] = p.size * (0.55 + t * .65)
      this.alphas[n] = Math.min(1, t * 2) * p.fade
      n++
    }
    this.geo.setDrawRange(0, n)
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aColor.needsUpdate = true
    this.geo.attributes.aSize.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
  }
}

export class Effects {
  constructor(scene, camera) {
    this.scene = scene
    this.camera = camera
    this.bloodTex = createParticleTexture(false)
    this.sparkTex = createParticleTexture(true)
    this.blood = new ParticlePool(scene, 900, false, this.bloodTex, 0x6b0a06)
    this.sparks = new ParticlePool(scene, 600, true, this.sparkTex, 0xffb35f)
    this.decals = []
    this.decalIndex = 0
    this.decalTexture = createBloodSplatTexture(256)
    this.debris = []
    this.slashes = []
    this.flashes = []
    this.floaters = []
    this.trauma = 0
    this.time = 0
    this.setupDecals()
    this.setupFlashPool()
  }

  setupDecals() {
    const geo = new THREE.PlaneGeometry(1, 1)
    for (let i = 0; i < 52; i++) {
      const mat = new THREE.MeshBasicMaterial({ map: this.decalTexture, transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -1 })
      const mesh = new THREE.Mesh(geo, mat)
      mesh.rotation.x = -Math.PI / 2
      mesh.position.y = .018
      mesh.visible = false
      mesh.renderOrder = 2
      this.scene.add(mesh)
      this.decals.push(mesh)
    }
  }

  setupFlashPool() {
    this.flashTex = createGlowTexture(128)
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.flashTex, color: 0xffc077, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 })
      const sprite = new THREE.Sprite(mat)
      sprite.visible = false
      this.scene.add(sprite)
      this.flashes.push({ sprite, life: 0, max: .2, start: 1 })
    }
  }

  bloodBurst(position, direction, amount = 20, power = 1) {
    const dir = direction ? direction.clone().normalize() : new THREE.Vector3(0, 0, 1)
    for (let i = 0; i < amount; i++) {
      const v = new THREE.Vector3(
        dir.x * rand(.4, 3.1) * power + rand(-1.3, 1.3),
        rand(.2, 2.4) * power + dir.y,
        dir.z * rand(.4, 3.1) * power + rand(-1.3, 1.3)
      )
      const color = new THREE.Color().setHSL(.012 + rand(-.01, .015), .82, rand(.09, .2))
      this.blood.spawn(
        { x: position.x + rand(-.14, .14), y: position.y + rand(-.18, .18), z: position.z + rand(-.14, .14) },
        v,
        { gravity: -11, drag: .9, life: rand(.45, 1.2), size: rand(.035, .115) * (power > 1 ? 1.3 : 1), color, floor: 0 }
      )
    }
    // mist
    for (let i = 0; i < Math.max(3, amount * .18); i++) {
      const color = new THREE.Color(0x4a0906)
      this.blood.spawn(
        { x: position.x, y: position.y, z: position.z },
        { x: rand(-.5, .5), y: rand(0, .6), z: rand(-.5, .5) },
        { gravity: .1, drag: 2, life: rand(.3, .7), size: rand(.15, .32), color, fade: .55 }
      )
    }
    this.addDecal(position, power)
  }

  addDecal(position, scale = 1) {
    const mesh = this.decals[this.decalIndex % this.decals.length]
    this.decalIndex++
    if (mesh.position.y < .015) mesh.position.y = .017 + rand(0, .006)
    mesh.position.set(position.x + rand(-.15, .15), .019 + rand(0, .006), position.z + rand(-.15, .15))
    mesh.rotation.z = rand(0, Math.PI * 2)
    const s = rand(.5, 1.4) * scale
    mesh.scale.set(s, s, 1)
    mesh.material.opacity = rand(.45, .78)
    mesh.visible = true
    mesh.userData.life = rand(16, 30)
    mesh.userData.maxLife = mesh.userData.life
  }

  sparksBurst(position, normal, amount = 15, power = 1) {
    const dir = normal ? normal.clone().normalize() : new THREE.Vector3(0, 1, 0)
    for (let i = 0; i < amount; i++) {
      const v = new THREE.Vector3(
        dir.x * rand(1, 4.5) + rand(-1.6, 1.6),
        rand(.1, 3.4) + dir.y,
        dir.z * rand(1, 4.5) + rand(-1.6, 1.6)
      ).multiplyScalar(power)
      const color = new THREE.Color().setHSL(rand(.055, .11), 1, rand(.5, .7))
      this.sparks.spawn(
        { x: position.x, y: position.y, z: position.z }, v,
        { gravity: -12, drag: .55, life: rand(.16, .6), size: rand(.025, .09), color, floor: 0 }
      )
    }
    this.impactFlash(position, 1.1 * power)
  }

  embers(position, amount = 10, color = 0xff7a3c) {
    for (let i = 0; i < amount; i++) {
      const c = new THREE.Color(color).offsetHSL(rand(-.02, .02), 0, rand(-.15, .15))
      this.sparks.spawn(
        { x: position.x + rand(-.4, .4), y: position.y, z: position.z + rand(-.4, .4) },
        { x: rand(-.4, .4), y: rand(.4, 1.8), z: rand(-.4, .4) },
        { gravity: .4, drag: .8, life: rand(.5, 1.6), size: rand(.025, .08), color: c }
      )
    }
  }

  dust(position, amount = 12, color = 0x9d8261, power = 1) {
    for (let i = 0; i < amount; i++) {
      const c = new THREE.Color(color)
      this.blood.spawn(
        { x: position.x + rand(-.2, .2), y: .05 + rand(0, .12), z: position.z + rand(-.2, .2) },
        { x: rand(-1.4, 1.4) * power, y: rand(.1, .7) * power, z: rand(-1.4, 1.4) * power },
        { gravity: -.15, drag: 1.8, life: rand(.4, .9), size: rand(.18, .4) * power, color: c, fade: .22 }
      )
    }
  }

  impactFlash(position, scale = 1, color = 0xffbe7a) {
    const f = this.flashes.find(x => x.life <= 0) || this.flashes[0]
    f.life = .19; f.max = .19; f.start = scale
    f.sprite.position.copy(position)
    f.sprite.material.color.set(color)
    f.sprite.scale.setScalar(.45 * scale)
    f.sprite.visible = true
  }

  spawnDebris(position, color, size = .16, velocity = null, type = 'metal') {
    const geo = Math.random() < .5 ? new THREE.BoxGeometry(size * rand(.7, 1.5), size * rand(.5, 1.3), size * rand(.4, .9)) : new THREE.TetrahedronGeometry(size * rand(.6, 1.2))
    const mat = new THREE.MeshStandardMaterial({ color, metalness: type === 'metal' ? .8 : .05, roughness: type === 'metal' ? .38 : .9 })
    const mesh = new THREE.Mesh(geo, mat)
    mesh.castShadow = true
    mesh.position.copy(position)
    this.scene.add(mesh)
    const v = velocity || new THREE.Vector3(rand(-2.8, 2.8), rand(1.5, 5), rand(-2.8, 2.8))
    this.debris.push({ mesh, v, av: new THREE.Vector3(rand(-8, 8), rand(-8, 8), rand(-8, 8)), life: rand(5, 8), floor: .04 + rand(0, .08) })
  }

  spawnHead(position, color, helmetColor) {
    const group = new THREE.Group()
    const head = new THREE.Mesh(new THREE.SphereGeometry(.16, 9, 7), new THREE.MeshStandardMaterial({ color, roughness: .7 }))
    head.scale.set(.94, 1.1, .96)
    group.add(head)
    if (helmetColor) {
      const helm = new THREE.Mesh(new THREE.SphereGeometry(.173, 9, 6, 0, Math.PI * 2, 0, Math.PI * .62), new THREE.MeshStandardMaterial({ color: helmetColor, metalness: .8, roughness: .33 }))
      helm.position.y = .04; group.add(helm)
    }
    group.position.copy(position)
    group.castShadow = true
    this.scene.add(group)
    this.debris.push({ mesh: group, v: new THREE.Vector3(rand(-2.5, 2.5), rand(3, 6), rand(-1, 2.5)), av: new THREE.Vector3(rand(-9, 9), rand(-9, 9), rand(-9, 9)), life: 9, floor: .18, head: true, blood: true })
    for (let i = 0; i < 24; i++) {
      this.blood.spawn({ x: position.x, y: position.y, z: position.z }, { x: rand(-2, 2), y: rand(1, 4), z: rand(-2, 2) }, { gravity: -11, drag: .7, life: rand(.5, 1.3), size: rand(.04, .11), color: new THREE.Color(0x5a0805) })
    }
  }

  slash(position, angle, heavy = false) {
    const inner = heavy ? 1.05 : .75
    const outer = heavy ? 3.0 : 2.55
    const theta = heavy ? 1.7 : 1.95
    const geo = new THREE.RingGeometry(inner, outer, 24, 1, -theta / 2, theta)
    const mat = new THREE.MeshBasicMaterial({ color: heavy ? 0xffa568 : 0xe8d3ae, transparent: true, opacity: .5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    const mesh = new THREE.Mesh(geo, mat)
    mesh.position.copy(position)
    mesh.position.y += heavy ? 1.3 : 1.1
    if (heavy) {
      mesh.rotation.set(0, -angle + Math.PI / 2, -.55)
    } else {
      mesh.rotation.set(-Math.PI / 2 + .32, 0, 0)
      mesh.rotation.z = -angle
    }
    this.scene.add(mesh)
    this.slashes.push({ mesh, life: .22, max: .22 })
  }

  floatText(position, text, cls = '') {
    const el = document.createElement('div')
    el.className = `float-num ${cls}`
    el.textContent = text
    document.getElementById('float-layer').appendChild(el)
    this.floaters.push({ el, position: position.clone(), life: .72 })
  }

  shake(amount) {
    this.trauma = clamp(this.trauma + amount, 0, 1.3)
  }

  getShake(dt) {
    if (this.trauma <= 0) return { x: 0, y: 0 }
    this.trauma = Math.max(0, this.trauma - dt * 1.8)
    const s = this.trauma * this.trauma
    return { x: (Math.sin(this.time * 91.3) + Math.sin(this.time * 57.1)) * .045 * s, y: (Math.cos(this.time * 83.7) + Math.sin(this.time * 47.9)) * .035 * s }
  }

  update(dt, camera = this.camera) {
    this.time += dt
    this.blood.update(dt)
    this.sparks.update(dt)
    for (const d of this.decals) {
      if (!d.visible) continue
      d.userData.life -= dt
      if (d.userData.life <= 0) { d.visible = false; continue }
      if (d.userData.life < 3) d.material.opacity = Math.max(0, d.material.opacity - dt * .18)
    }
    for (let i = this.debris.length - 1; i >= 0; i--) {
      const d = this.debris[i]
      d.life -= dt
      if (d.life <= 0) {
        this.scene.remove(d.mesh)
        d.mesh.traverse?.(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose() })
        this.debris.splice(i, 1)
        continue
      }
      d.v.y -= 15 * dt
      d.mesh.position.addScaledVector(d.v, dt)
      if (d.mesh.position.y < d.floor) {
        d.mesh.position.y = d.floor
        if (Math.abs(d.v.y) > 1.2) { d.v.y *= -.28; d.v.x *= .65; d.v.z *= .65 } else { d.v.y = 0; d.v.multiplyScalar(.94) }
        d.av.multiplyScalar(.93)
        if (d.head && Math.random() < .15) this.blood.spawn({ x: d.mesh.position.x, y: d.mesh.position.y, z: d.mesh.position.z }, { x: rand(-.3, .3), y: .2, z: rand(-.3, .3) }, { gravity: -9, drag: 1, life: .4, size: .05, color: new THREE.Color(0x500704) })
      }
      d.mesh.rotation.x += d.av.x * dt
      d.mesh.rotation.y += d.av.y * dt
      d.mesh.rotation.z += d.av.z * dt
      if (!d.head && d.mesh.position.y <= d.floor + .1) d.v.x *= .985
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i]
      s.life -= dt
      if (s.life <= 0) {
        this.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose(); this.slashes.splice(i, 1); continue
      }
      const k = 1 - s.life / s.max
      s.mesh.scale.setScalar(1 + k * .34)
      s.mesh.material.opacity = (1 - k) * .42
    }
    for (const f of this.flashes) {
      if (f.life <= 0) continue
      f.life -= dt
      const k = 1 - f.life / f.max
      f.sprite.scale.setScalar(f.start * (.45 + k * 1.9))
      f.sprite.material.opacity = (1 - k) * .7
      if (f.life <= 0) f.sprite.visible = false
    }
    for (let i = this.floaters.length - 1; i >= 0; i--) {
      const f = this.floaters[i]
      f.life -= dt
      if (f.life <= 0) { f.el.remove(); this.floaters.splice(i, 1); continue }
      const p = f.position.clone().project(camera)
      const x = (p.x * .5 + .5) * window.innerWidth
      const y = (-p.y * .5 + .5) * window.innerHeight
      f.el.style.left = `${x}px`
      f.el.style.top = `${y}px`
    }
  }
}

import * as THREE from 'three'
import { WEAPONS, ARMORS } from './weapons.js'
import { ENEMY_TYPES } from './character.js'
import { formatNumber, clamp, roman } from './utils.js'

const $ = id => document.getElementById(id)

export class UI {
  constructor(audio) {
    this.audio = audio
    this.handlers = {}
    this.currentOverlay = null
    this.layout = 'desktop'
    this.enemyEls = new Map()
    this.bossEnemy = null
    this.lastHealth = 100
    this.armoryState = { tab: 'weapons', selected: null }
    this.dom = {
      loading: $('loading-screen'), title: $('title-screen'), hud: $('hud'),
      health: $('health-bar'), healthLag: $('health-lag'), healthText: $('health-text'),
      stamina: $('stamina-bar'), armorChip: $('armor-chip'), combo: $('combo-chip'),
      wave: $('wave-label'), arena: $('arena-name'), objective: $('wave-objective'), pips: $('wave-pips'),
      score: $('score-value'), marks: $('marks-value'), chain: $('chain-value'), chainTimer: $('chain-timer'),
      rage: $('rage-bar'), rageText: $('rage-text'), weapon: $('hud-weapon'),
      statReach: $('stat-reach'), statHit: $('stat-hit'),
      bossHud: $('boss-hud'), bossName: $('boss-name'), bossFill: $('boss-fill'),
      announce: $('announcement'), announceKicker: $('announce-kicker'), announceTitle: $('announce-title'), announceSub: $('announce-sub'),
      prompt: $('execution-prompt'), slow: $('slowmo-vignette'), hitmarker: $('hit-marker'),
      damage: $('damage-flash'), blood: $('blood-screen'), parry: $('parry-flash'),
      reticle: $('reticle'), touch: $('touch-ui'), executeBtn: document.querySelector('[data-touch="execute"]'),
      staminaWarning: $('stamina-warning'), controls: $('control-ribbon'),
      pause: $('pause-screen'), settings: $('settings-screen'), armory: $('armory-screen'),
      boon: $('boon-screen'), codex: $('codex-screen'), death: $('death-screen')
    }
    this.bindStatic()
  }

  bindStatic() {
    const click = (id, fn) => $(id)?.addEventListener('click', () => { this.audio.ui(true); fn() })
    click('btn-start', () => this.handlers.start?.())
    click('btn-armory', () => this.handlers.armory?.())
    click('btn-settings', () => this.handlers.settings?.())
    click('btn-codex', () => this.handlers.codex?.())
    click('btn-resume', () => this.handlers.resume?.())
    click('btn-pause-settings', () => this.handlers.settings?.())
    click('btn-abandon', () => this.handlers.abandon?.())
    click('btn-retry', () => this.handlers.retry?.())
    click('btn-menu', () => this.handlers.menu?.())
    click('btn-next-wave', () => this.handlers.nextWave?.())
    document.querySelectorAll('[data-close]').forEach(btn => {
      btn.addEventListener('click', () => {
        this.audio.ui()
        const name = btn.dataset.close
        if (name === 'settings') this.handlers.closeSettings?.()
        else this.closeOverlay(name)
      })
    })
    document.querySelectorAll('.tab').forEach(tab => {
      tab.addEventListener('click', () => {
        this.audio.ui()
        this.armoryState.tab = tab.dataset.tab
        this.renderArmory()
      })
    })
    // settings
    const vol = $('set-volume'), sens = $('set-sens'), gore = $('set-gore'), scale = $('set-scale'), shake = $('set-shake'), motion = $('set-motion')
    const updateLabel = () => {
      $('vol-val').textContent = `${vol.value}%`
      $('sens-val').textContent = (sens.value / 100).toFixed(1)
      $('gore-val').textContent = ['SUBTLE', 'STANDARD', 'CINEMATIC'][gore.value]
      $('scale-val').textContent = ['AUTO', 'HIGH', 'PERFORMANCE'][scale.value]
    }
    vol.addEventListener('input', () => { updateLabel(); this.handlers.setting?.('volume', Number(vol.value)) })
    sens.addEventListener('input', () => { updateLabel(); this.handlers.setting?.('sensitivity', Number(sens.value)) })
    gore.addEventListener('input', () => { updateLabel(); this.handlers.setting?.('gore', Number(gore.value)) })
    scale.addEventListener('input', () => { updateLabel(); this.handlers.setting?.('scale', Number(scale.value)) })
    shake.addEventListener('change', () => this.handlers.setting?.('shake', shake.checked))
    motion.addEventListener('change', () => this.handlers.setting?.('motion', motion.checked))
    updateLabel()
  }

  bind(handlers) { this.handlers = handlers }

  setSettings(settings) {
    $('set-volume').value = Math.round(settings.volume * 100)
    $('set-sens').value = settings.sensitivity
    $('set-gore').value = settings.gore
    $('set-scale').value = settings.scale
    $('set-shake').checked = settings.shake
    $('set-motion').checked = settings.motion
    $('vol-val').textContent = `${Math.round(settings.volume * 100)}%`
    $('sens-val').textContent = (settings.sensitivity / 100).toFixed(1)
    $('gore-val').textContent = ['SUBTLE', 'STANDARD', 'CINEMATIC'][settings.gore]
    $('scale-val').textContent = ['AUTO', 'HIGH', 'PERFORMANCE'][settings.scale]
  }

  hideLoading() {
    this.dom.loading.classList.add('is-leaving')
    setTimeout(() => this.dom.loading.classList.remove('is-active'), 600)
  }

  showTitle() {
    document.body.classList.remove('in-game')
    this.dom.title.classList.add('is-active')
    this.dom.title.classList.remove('is-leaving')
    this.dom.hud.setAttribute('aria-hidden', 'true')
    this.clearEnemyBars()
  }

  hideTitle() {
    this.dom.title.classList.add('is-leaving')
    setTimeout(() => { this.dom.title.classList.remove('is-active') }, 600)
  }

  enterGame() {
    document.body.classList.add('in-game')
    this.dom.hud.setAttribute('aria-hidden', 'false')
    this.controlHint()
  }

  controlHint() {
    this.dom.controls.classList.remove('hide')
    clearTimeout(this.controlTimer)
    this.controlTimer = setTimeout(() => this.dom.controls.classList.add('hide'), 9000)
  }

  setTouch(enabled) {
    document.body.classList.toggle('touch', enabled)
    this.touchEnabled = enabled
  }

  updateTitleLoadout(meta) {
    const w = WEAPONS.find(w => w.id === meta.weapon) || WEAPONS[0]
    const a = ARMORS.find(a => a.id === meta.armor) || ARMORS[0]
    $('title-weapon').textContent = w.name
    $('title-weapon-glyph').textContent = w.icon
    $('title-armor').textContent = `${a.name} · RANK ${meta.rank || 1}`
    $('title-renown').textContent = formatNumber(meta.renown || 0)
    const next = this.xpForRank(meta.rank || 1)
    $('title-xp').style.width = `${clamp(((meta.renown || 0) % next) / next * 100, 2, 100)}%`
  }

  xpForRank(rank) { return 500 + rank * 230 }

  updateHUD(data) {
    const d = this.dom
    d.health.style.width = `${clamp(data.health / data.maxHealth * 100, 0, 100)}%`
    d.healthText.textContent = Math.ceil(data.health)
    if (data.health < this.lastHealth) d.healthLag.style.width = `${clamp(data.health / data.maxHealth * 100, 0, 100)}%`
    else setTimeout(() => { d.healthLag.style.width = `${clamp(data.health / data.maxHealth * 100, 0, 100)}%` }, 300)
    this.lastHealth = data.health
    d.stamina.style.width = `${clamp(data.stamina / data.maxStamina * 100, 0, 100)}%`
    d.armorChip.textContent = data.armor > 0 ? `PLATE ${Math.ceil(data.armor / data.maxArmor * 100)}%` : 'PLATE BROKEN'
    d.combo.textContent = data.combo > 1 ? `${data.combo} HIT CHAIN` : 'NO CHAIN'
    d.score.textContent = String(Math.floor(data.score)).padStart(6, '0')
    d.marks.textContent = formatNumber(data.runMarks)
    d.chain.textContent = `×${data.chain.toFixed(2)}`
    d.chainTimer.style.transform = `scaleX(${clamp(data.chainTimer, 0, 1)})`
    d.rage.style.width = `${clamp(data.rage, 0, 100)}%`
    d.rageText.textContent = Math.floor(data.rage)
    d.weapon.textContent = data.weaponName
    d.statReach.style.width = `${clamp(data.reach / 3.5 * 100, 10, 100)}%`
    d.statHit.style.width = `${clamp(data.damage / 105 * 100, 10, 100)}%`
    d.staminaWarning.classList.toggle('on', data.stamina < 14)
    d.executeBtn?.classList.toggle('show', !!data.executable)
    d.prompt.classList.toggle('show', !!data.executable)
    d.slow.classList.toggle('on', !!data.slowmo)
  }

  setWave(wave, arenaName, objective, boss = false) {
    this.dom.wave.textContent = `WAVE ${roman(wave)}`
    this.dom.arena.textContent = arenaName
    this.dom.objective.textContent = objective
    let html = ''
    const pips = Math.min(10, Math.max(10, Math.ceil(wave / 5) * 5))
    for (let i = 1; i <= pips; i++) html += `<i class="${i < wave ? 'filled' : ''} ${i % 5 === 0 ? 'boss' : ''}"></i>`
    this.dom.pips.innerHTML = html
  }

  setBoss(enemy) {
    this.bossEnemy = enemy
    this.dom.bossHud.classList.toggle('active', !!enemy)
    if (enemy) {
      this.dom.bossName.textContent = enemy.def.name
      this.dom.bossName.parentElement.querySelector('span').textContent = enemy.def.title
    }
  }

  updateEnemyBars(enemies, camera) {
    const layer = $('enemy-layer')
    const current = new Set()
    const v = new THREE.Vector3()
    for (const e of enemies) {
      if (e.char.dead || e.removed) continue
      current.add(e.id)
      let entry = this.enemyEls.get(e.id)
      if (!entry) {
        const el = document.createElement('div')
        el.className = `enemy-bar ${e.def.boss ? 'boss' : ''}`
        el.innerHTML = `<div class="name"><span>${e.def.name}</span><b>${e.char.health > 0 ? Math.ceil(e.char.health) : ''}</b></div><div class="track"><i></i></div>`
        layer.appendChild(el)
        entry = { el, fill: el.querySelector('.track i'), name: el.querySelector('.name b') }
        this.enemyEls.set(e.id, entry)
      }
      e.char.getHeadPosition(v)
      v.y += .42
      const p = v.clone().project(camera)
      const dist = camera.position.distanceTo(v)
      const visible = p.z < 1 && dist < 26 && dist > 1.4
      entry.el.classList.toggle('show', visible)
      if (visible) {
        entry.el.style.left = `${(p.x * .5 + .5) * window.innerWidth}px`
        entry.el.style.top = `${(-p.y * .5 + .5) * window.innerHeight}px`
        entry.fill.style.width = `${clamp(e.char.health / e.char.maxHealth * 100, 0, 100)}%`
        entry.name.textContent = Math.ceil(e.char.health)
      }
    }
    for (const [id, entry] of this.enemyEls) {
      if (!current.has(id)) { entry.el.remove(); this.enemyEls.delete(id) }
    }
    if (this.bossEnemy) {
      const e = this.bossEnemy
      if (e.char.dead || e.removed) { this.setBoss(null) } else {
        this.dom.bossFill.style.width = `${clamp(e.char.health / e.char.maxHealth * 100, 0, 100)}%`
      }
    }
  }

  clearEnemyBars() {
    for (const [, entry] of this.enemyEls) entry.el.remove()
    this.enemyEls.clear()
    this.setBoss(null)
  }

  setReticle(lock) { this.dom.reticle.classList.toggle('lock', lock) }

  showAnnouncement(kicker, title, sub, boss = false, duration = 2300) {
    const d = this.dom
    d.announceKicker.textContent = kicker
    d.announceTitle.textContent = title
    d.announceSub.textContent = sub
    d.announce.classList.toggle('boss', boss)
    d.announce.classList.add('show')
    clearTimeout(this.announceTimer)
    this.announceTimer = setTimeout(() => d.announce.classList.remove('show'), duration)
  }

  toast(text, type = '') {
    const el = document.createElement('div')
    el.className = `toast ${type}`
    el.textContent = text
    $('toast-layer').appendChild(el)
    setTimeout(() => el.remove(), 3300)
  }

  flashDamage() {
    this.dom.damage.classList.add('hit')
    setTimeout(() => this.dom.damage.classList.remove('hit'), 100)
  }

  flashBlood() {
    this.dom.blood.classList.add('active')
    clearTimeout(this.bloodTimer)
    this.bloodTimer = setTimeout(() => this.dom.blood.classList.remove('active'), 1200)
  }

  flashParry() {
    this.dom.parry.classList.remove('on')
    void this.dom.parry.offsetWidth
    this.dom.parry.classList.add('on')
  }

  hitMarker(heavy = false) {
    this.dom.hitmarker.classList.remove('on')
    void this.dom.hitmarker.offsetWidth
    this.dom.hitmarker.style.borderColor = heavy ? 'rgba(255,106,63,.95)' : 'rgba(255,238,210,.9)'
    this.dom.hitmarker.classList.add('on')
  }

  showSlowmo(on) { this.dom.slow.classList.toggle('on', on) }

  openOverlay(name) {
    const el = this[name === 'boons' ? 'boon' : name]
    if (!el) return
    this.currentOverlay = name
    el.classList.add('is-active')
    if (name === 'pause' || name === 'settings' || name === 'armory' || name === 'codex') {
      this.dom.hud.style.opacity = name === 'pause' ? '.25' : '.12'
    }
  }

  closeOverlay(name) {
    const el = this[name === 'boons' ? 'boon' : name]
    if (!el) return
    el.classList.remove('is-active')
    this.currentOverlay = null
    this.dom.hud.style.opacity = ''
    if (name === 'settings') this.handlers.closeSettings?.()
  }

  closeAllOverlays() {
    for (const el of [this.dom.pause, this.dom.settings, this.dom.armory, this.dom.codex, this.dom.boon, this.dom.death]) el.classList.remove('is-active')
    this.currentOverlay = null
    this.dom.hud.style.opacity = ''
  }

  showPause(show) {
    this.dom.pause.classList.toggle('is-active', show)
    this.dom.hud.style.opacity = show ? '.25' : ''
  }

  setPauseStats(wave, kills, score) {
    $('pause-wave').textContent = roman(wave)
    $('pause-kills').textContent = kills
    $('pause-score').textContent = formatNumber(score)
  }

  renderArmory(meta = this.armoryMeta, loadout = this.armoryLoadout) {
    if (!meta) return
    this.armoryMeta = meta
    this.armoryLoadout = loadout
    const grid = $('armory-grid')
    const tab = this.armoryState.tab
    $('armory-marks').textContent = formatNumber(meta.marks)
    $('armory-progress').textContent = `BEST WAVE — ${roman(meta.bestWave || 0)}`
    document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.tab === tab))
    if (tab === 'boons') {
      grid.innerHTML = `<div class="gear-card" style="grid-column:1/-1;cursor:default;min-height:120px"><div class="gear-icon">✦</div><strong>BOONS OF THE FALLEN</strong><span>Survive a wave to claim a boon. Boons are lost when you fall.</span><div style="color:#8d7a60;font-size:12px;margin-top:12px;line-height:1.5">Each wave offers three gifts. Choose one: heal, harden your hide, sharpen your steel, or feed on the dying. Bosses grant greater boons.</div></div>`
      if (!this.armoryState.selected || !this.armoryState.selected.startsWith('boon')) this.armoryState.selected = 'boon-info'
      this.renderDetail({ id: 'boon-info', name: 'THE ARENA REMEMBERS', type: 'PROGRESSION', icon: '✦', desc: 'The crowd rewards endurance. Each wave cleared grants Bloodmarks and a boon. Fall, and the run ends — but your weapons and armor remain.', stats: [['RENOWN', 78], ['BLOODMARKS', 60], ['SURVIVAL', 42]], owned: true, equipped: true, cost: 0 })
      return
    }
    const list = tab === 'weapons' ? WEAPONS : ARMORS
    const unlocked = tab === 'weapons' ? meta.unlockedWeapons : meta.unlockedArmor
    const equipped = tab === 'weapons' ? loadout.weapon : loadout.armor
    grid.innerHTML = ''
    for (const item of list) {
      const owned = unlocked.includes(item.id)
      const el = document.createElement('button')
      const cardEquipped = equipped === item.id
      el.className = `gear-card ${owned ? '' : 'locked'} ${cardEquipped ? 'equipped' : ''} ${this.armoryState.selected === item.id ? 'selected' : ''}`
      el.innerHTML = `<div class="gear-icon">${item.icon}</div><strong>${item.name}</strong><span>${item.type}</span><span class="gear-cost ${owned ? 'owned' : ''}">${cardEquipped ? 'EQUIPPED' : owned ? 'OWNED' : `${formatNumber(item.cost)} BLOODMARKS`}</span>`
      el.addEventListener('click', () => { this.audio.ui(); this.armoryState.selected = item.id; this.renderArmory(meta, loadout) })
      grid.appendChild(el)
      if (!this.armoryState.selected || !list.find(x => x.id === this.armoryState.selected)) this.armoryState.selected = list[0].id
    }
    const selected = list.find(x => x.id === this.armoryState.selected) || list[0]
    const owned = unlocked.includes(selected.id)
    const stats = tab === 'weapons' ? [
      ['DAMAGE', selected.damage / 105 * 100],
      ['REACH', selected.reach / 3.5 * 100],
      ['SPEED', selected.speed * 100],
      ['STAGGER', selected.stagger / 2.2 * 100]
    ] : [
      ['VITALITY', selected.health / 140 * 100],
      ['STAMINA', selected.stamina / 130 * 100],
      ['DEFENSE', selected.defense / .34 * 100],
      ['MOBILITY', selected.speed / 1.15 * 100]
    ]
    this.renderDetail({
      ...selected,
      owned: unlocked.includes(selected.id),
      equipped: equipped === selected.id,
      stats,
      canAfford: meta.marks >= selected.cost
    })
  }

  renderDetail(item) {
    $('detail-type').textContent = item.type
    $('detail-name').textContent = item.name
    $('detail-desc').textContent = item.desc
    $('armory-icon').textContent = item.icon
    const stats = $('detail-stats')
    stats.innerHTML = ''
    for (const [name, value] of item.stats || []) {
      stats.innerHTML += `<div class="detail-stat"><span>${name}</span><i><b style="width:${clamp(value, 3, 100)}%"></b></i></div>`
    }
    const btn = $('armory-action')
    if (item.equipped) { btn.textContent = 'EQUIPPED'; btn.disabled = true }
    else if (item.owned) { btn.textContent = 'EQUIP'; btn.disabled = false }
    else if (item.canAfford) { btn.textContent = `UNLOCK — ${formatNumber(item.cost)}`; btn.disabled = false }
    else { btn.textContent = `NEED ${formatNumber(item.cost - (this.armoryMeta?.marks || 0))} MORE`; btn.disabled = true }
    btn.onclick = () => {
      if (item.id === 'boon-info') return
      this.handlers.armoryAction?.(this.armoryState.tab, item.id)
    }
  }

  showArmory(meta, loadout) {
    this.openOverlay('armory')
    this.renderArmory(meta, loadout)
  }

  showBoons(wave, boons, reward, onChoose) {
    this.openOverlay('boons')
    $('boon-wave').textContent = roman(wave)
    $('boon-reward').textContent = `+${formatNumber(reward)} BLOODMARKS`
    const grid = $('boon-grid')
    grid.innerHTML = ''
    this.selectedBoon = null
    const next = $('btn-next-wave')
    next.disabled = true
    next.textContent = 'CHOOSE A BOON'
    for (const boon of boons) {
      const el = document.createElement('button')
      el.className = 'boon-card'
      el.innerHTML = `<div class="boon-sigil">${boon.icon}</div><div><h3>${boon.name}</h3><p>${boon.desc}</p><em>${boon.rarity}</em></div>`
      el.addEventListener('click', () => {
        this.audio.ui(true)
        grid.querySelectorAll('.boon-card').forEach(c => c.classList.remove('selected'))
        el.classList.add('selected')
        this.selectedBoon = boon
        next.disabled = false
        next.textContent = 'CLAIM & ENTER THE NEXT WAVE'
      })
      grid.appendChild(el)
    }
    next.onclick = () => {
      if (!this.selectedBoon) return
      this.handlers.boonChosen?.(this.selectedBoon)
      this.closeOverlay('boons')
      onChoose?.(this.selectedBoon)
    }
  }

  showDeath(data) {
    this.dom.hud.style.opacity = '.1'
    this.dom.death.classList.add('is-active')
    $('death-wave').textContent = roman(data.wave)
    $('death-kills').textContent = data.kills
    $('death-score').textContent = formatNumber(data.score)
    $('death-marks').textContent = `+${formatNumber(data.marks)}`
    $('death-sub').textContent = data.boss ? `FELLED BY ${data.boss}` : 'YOUR NAME JOINS THE SAND'
  }

  hideDeath() {
    this.dom.death.classList.remove('is-active')
    this.dom.hud.style.opacity = ''
  }

  hideGameUI() {
    document.body.classList.remove('in-game')
    this.dom.hud.style.opacity = ''
    this.dom.hud.setAttribute('aria-hidden', 'true')
    this.clearEnemyBars()
    this.showSlowmo(false)
    this.setBoss(null)
  }

  showError(message) {
    const el = $('boot-error')
    el.hidden = false
    el.textContent = message
  }
}

import * as THREE from 'three'
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'
import { Character, ENEMY_TYPES } from './character.js'
import { Arena, ARENAS, createEnvironmentMap } from './arena.js'
import { Effects } from './effects.js'
import { AudioEngine } from './audio.js'
import { UI } from './ui.js'
import { WEAPONS, ARMORS, getWeapon, getArmor } from './weapons.js'
import { clamp, damp, dampAngle, rand, randInt, pick, chance, roman, shortestAngle, formatNumber } from './utils.js'

const SAVE_KEY = 'iron-requiem-save-v1'
const SETTINGS_KEY = 'iron-requiem-settings-v1'

const BOONS = [
  { id: 'iron-skin', name: 'IRON SKIN', icon: '⬢', desc: 'Gain 20 maximum Vitality and heal 20. The plate grows around your bones.', rarity: 'FORTITUDE', apply: g => { g.maxHealth += 20; g.player.char.maxHealth += 20; g.heal(20) } },
  { id: 'second-wind', name: 'SECOND WIND', icon: '≋', desc: 'Gain 24 maximum Stamina and regenerate it 20% faster.', rarity: 'ENDURANCE', apply: g => { g.maxStamina += 24; g.staminaRegen *= 1.2 } },
  { id: 'keen-edge', name: 'KEEN EDGE', icon: '⟡', desc: 'All weapon damage increased by 14%.', rarity: 'STEEL', apply: g => { g.damageMul *= 1.14 } },
  { id: 'bloodthirst', name: 'BLOODTHIRST', icon: '♨', desc: 'Heal for 9% of all damage dealt. The fallen feed you.', rarity: 'HUNGER', apply: g => { g.lifesteal += .09 } },
  { id: 'butchers-rhythm', name: "BUTCHER'S RHYTHM", icon: '⌁', desc: 'Attacks and dodges cost 22% less Stamina.', rarity: 'TEMPO', apply: g => { g.staminaCostMul *= .78 } },
  { id: 'thick-blood', name: 'THICK BLOOD', icon: '◉', desc: 'Take 14% less damage from all sources.', rarity: 'SURVIVAL', apply: g => { g.damageTakenMul *= .86 } },
  { id: 'executioner', name: "EXECUTIONER'S DUE", icon: '☠', desc: 'Executions cost 10 less Bloodlust and restore 30 Vitality.', rarity: 'CRUELTY', apply: g => { g.executeCost = Math.max(20, g.executeCost - 10); g.executeHeal += 18 } },
  { id: 'ruin', name: 'RUIN', icon: '✦', desc: 'Armor breaks 55% faster under your blows.', rarity: 'RUIN', apply: g => { g.breakMul *= 1.55 } },
  { id: 'warlords-stride', name: "WARLORD'S STRIDE", icon: '➤', desc: 'Move 10% faster and dodge 15% farther.', rarity: 'MOTION', apply: g => { g.moveSpeedMul *= 1.1; g.dodgeMul *= 1.15 } },
  { id: 'blood-price', name: 'BLOOD PRICE', icon: '♦', desc: 'Gain 40 Bloodlust at the start of every wave.', rarity: 'RAGE', apply: g => { g.waveRage += 40 } }
]

function loadJSON(key, fallback) {
  try {
    const v = JSON.parse(localStorage.getItem(key))
    return v && typeof v === 'object' ? { ...fallback, ...v } : fallback
  } catch { return fallback }
}

export class Game {
  constructor() {
    this.canvas = document.getElementById('stage')
    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, .07, 260)
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, powerPreference: 'high-performance', stencil: false })
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping
    this.renderer.toneMappingExposure = 1.06
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    this.renderer.setClearColor(0x080605, 1)
    this.applyPixelRatio()

    this.composer = new EffectComposer(this.renderer)
    this.renderPass = new RenderPass(this.scene, this.camera)
    this.composer.addPass(this.renderPass)
    this.bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth * .55, innerHeight * .55), .46, .68, .82)
    this.composer.addPass(this.bloom)
    this.composer.addPass(new OutputPass())

    this.clock = new THREE.Clock()
    this.time = 0
    this.realTime = 0
    this.state = 'title'
    this.arena = new Arena(this.scene, this.renderer)
    this.audio = new AudioEngine()
    this.ui = new UI(this.audio)
    this.meta = loadJSON(SAVE_KEY, {
      marks: 0, unlockedWeapons: ['ashen-longsword'], unlockedArmor: ['vigil-plate'],
      weapon: 'ashen-longsword', armor: 'vigil-plate', bestWave: 0, renown: 0, kills: 0, runs: 0
    })
    this.settings = loadJSON(SETTINGS_KEY, { volume: .75, sensitivity: 100, gore: 2, scale: 0, shake: true, motion: false })
    this.weapon = getWeapon(this.meta.weapon)
    this.armor = getArmor(this.meta.armor)
    this.enemies = []
    this.enemyId = 1
    this.spawnQueue = []
    this.spawnTimer = 0
    this.activeLimit = 2
    this.yaw = 0
    this.pitch = .2
    this.cameraDist = 4.8
    this.cameraShoulder = .62
    this.intro = 1
    this.timeScale = 1
    this.slowmoTimer = 0
    this.freezeTimer = 0
    this.hitstop = 0
    this.execution = null
    this.deathTimer = 0
    this.deathShown = false
    this.waveClearTimer = -1
    this.wave = 1
    this.themeIndex = 0
    this.waveActive = false
    this.keys = {}
    this.touch = { active: false, moveX: 0, moveY: 0, lookId: null, lastX: 0, lastY: 0 }
    this.attackBuffer = null
    this.uiTimer = 0
    this.lastStep = 0
    this.pointerLocked = false
    this.shakeEnabled = this.settings.shake && !this.settings.motion

    this.scene.environment = createEnvironmentMap(this.renderer)
    this.scene.environmentIntensity = .72
    this.setupWorld()
    this.ui.setSettings(this.settings)
    this.ui.updateTitleLoadout(this.meta)
    this.audio.setVolume(this.settings.volume)
    this.bindUI()
    this.bindInput()
    this.resetRunData()
    this.spawnPlayer()
    this.arena.build(0)
    this.player.root.position.set(0, 0, 3.1)
    this.player.root.rotation.y = .16
    this.player.state = 'idle'
    this.player.speedActual = 0
    this.ui.showTitle()
    this.ui.setTouch(this.isTouchDevice())
    this.resize()
    addEventListener('resize', () => this.resize())
    this.animate = this.animate.bind(this)
    this.animate()
    setTimeout(() => this.ui.hideLoading(), 260)
  }

  applyPixelRatio() {
    const cap = this.settings?.scale === 2 ? 1 : this.settings?.scale === 1 ? 2 : 1.5
    this.renderer.setPixelRatio(Math.min(devicePixelRatio || 1, cap))
  }

  resize() {
    const w = innerWidth, h = innerHeight
    this.camera.aspect = w / h
    this.camera.updateProjectionMatrix()
    this.renderer.setSize(w, h, false)
    this.composer.setSize(w, h)
    this.bloom.setSize(w * .55, h * .55)
    this.applyPixelRatio()
  }

  isTouchDevice() {
    return matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window || navigator.maxTouchPoints > 0
  }

  setupWorld() {
    // A warm rim light follows the action without casting shadows.
    this.rimLight = new THREE.PointLight(0xffbd7c, 2.3, 14, 2)
    this.scene.add(this.rimLight)
    this.playerLight = new THREE.PointLight(0xaacbff, .8, 10, 2)
    this.scene.add(this.playerLight)
  }

  spawnPlayer() {
    if (this.player) {
      this.player.dispose()
      this.scene.remove(this.player.root)
    }
    const armor = getArmor(this.meta.armor)
    const weapon = getWeapon(this.meta.weapon)
    this.weapon = weapon
    this.armor = armor
    this.baseMaxHealth = armor.health
    this.baseMaxStamina = armor.stamina
    this.maxHealth = this.baseMaxHealth
    this.maxStamina = this.baseMaxStamina
    this.damageMul = 1
    this.staminaRegen = 21
    this.staminaCostMul = 1
    this.damageTakenMul = 1
    this.lifesteal = 0
    this.breakMul = 1
    this.moveSpeedMul = 1
    this.dodgeMul = 1
    this.executeCost = 40
    this.executeHeal = 12
    this.waveRage = 0
    this.player = new Character(this.scene, {
      player: true, health: this.maxHealth, armor: 100,
      weaponData: weapon, healthScale: 1
    })
    this.player.maxHealth = this.maxHealth
    this.player.health = this.maxHealth
    this.player.speed = 4.0 * armor.speed
    this.player.root.position.set(0, 0, 8)
    this.player.root.rotation.y = Math.PI
    this.player.onArmorBreak = piece => this.onPlayerArmorBreak(piece)
    this.player.getWeaponTip()
  }

  resetRunData() {
    this.wave = 1
    this.kills = 0
    this.score = 0
    this.runMarks = 0
    this.chain = 1
    this.chainTimer = 0
    this.rage = 0
    this.combo = 0
    this.comboWindow = 0
    this.stamina = this.maxStamina || 100
    this.staminaDelay = 0
    this.blockStart = -10
    this.blocking = false
    this.blockBroken = false
    this.lastDamageTime = -10
    this.attackCooldown = 0
    this.attackStep = 0
    this.playerInvuln = 0
    this.hazardCooldown = 0
    this.waveActive = false
    this.spawnQueue = []
    this.spawnTimer = 0
    this.waveClearTimer = -1
    this.deathTimer = 0
    this.deathShown = false
    this.boons = []
    this.boonChoices = []
    this.enemyAttacks = 0
    this.runStart = this.realTime
    this.themeIndex = 0
    this.playerKnockback = new THREE.Vector3()
  }

  bindUI() {
    this.ui.bind({
      start: () => this.startRun(),
      armory: () => this.openArmory('title'),
      settings: () => this.openSettings(),
      codex: () => this.ui.openOverlay('codex'),
      resume: () => this.resume(),
      abandon: () => this.abandonRun(),
      retry: () => { this.ui.closeAllOverlays(); this.startRun() },
      menu: () => { this.ui.closeAllOverlays(); this.toTitle() },
      nextWave: () => this.nextWave(),
      boonChosen: boon => this.chooseBoon(boon),
      setting: (key, value) => this.changeSetting(key, value),
      closeSettings: () => this.closeSettings(),
      armoryAction: (tab, id) => this.armoryAction(tab, id)
    })
  }

  bindInput() {
    const keyMap = { KeyW: 'forward', KeyS: 'back', KeyA: 'left', KeyD: 'right', ShiftLeft: 'sprint', ShiftRight: 'sprint', Space: 'dodge', KeyQ: 'heavy', KeyE: 'execute' }
    addEventListener('keydown', e => {
      if (e.code === 'Escape') { e.preventDefault(); this.togglePause(); return }
      if (e.code === 'Tab') e.preventDefault()
      const k = keyMap[e.code]
      if (k) this.keys[k] = true
      if (this.state !== 'playing' || this.ui.currentOverlay) return
      if (e.code === 'Space') { e.preventDefault(); this.tryDodge() }
      if (e.code === 'KeyQ') { e.preventDefault(); this.tryAttack('heavy') }
      if (e.code === 'KeyE') { e.preventDefault(); this.tryExecute() }
    })
    addEventListener('keyup', e => {
      const k = keyMap[e.code]
      if (k) this.keys[k] = false
    })
    this.canvas.addEventListener('mousedown', e => {
      if (this.state !== 'playing' || this.ui.currentOverlay) return
      if (e.button === 0) {
        if (!this.pointerLocked && !this.isTouchDevice()) this.requestLock()
        this.tryAttack('light')
      } else if (e.button === 2) {
        this.startBlock()
      }
    })
    addEventListener('mouseup', e => {
      if (e.button === 2) this.endBlock()
    })
    this.canvas.addEventListener('contextmenu', e => e.preventDefault())
    document.addEventListener('mousemove', e => {
      if (this.state !== 'playing' || this.ui.currentOverlay) return
      if (!this.pointerLocked && !this.touch.dragging) return
      if (this.touch.dragging) return
      this.yaw -= e.movementX * (this.settings.sensitivity / 100) * .0022
      this.pitch = clamp(this.pitch + e.movementY * (this.settings.sensitivity / 100) * .0017, -.18, .82)
    })
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas
      if (!this.pointerLocked) this.endBlock()
    })
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pause()
    })
    this.bindTouch()
  }

  requestLock() {
    if (this.isTouchDevice()) return
    try { this.canvas.requestPointerLock() } catch {}
  }

  bindTouch() {
    const stick = document.getElementById('joystick')
    const knob = stick.querySelector('b')
    let stickId = null
    const updateStick = (e) => {
      const r = stick.getBoundingClientRect()
      const x = (e.clientX - r.left - r.width / 2) / (r.width / 2)
      const y = (e.clientY - r.top - r.height / 2) / (r.height / 2)
      const len = Math.hypot(x, y)
      const nx = len > 1 ? x / len : x
      const ny = len > 1 ? y / len : y
      this.touch.moveX = nx
      this.touch.moveY = ny
      knob.style.transform = `translate(${nx * 27}px, ${ny * 27}px)`
    }
    stick.addEventListener('pointerdown', e => {
      stickId = e.pointerId; stick.setPointerCapture(e.pointerId); updateStick(e); e.preventDefault()
    })
    stick.addEventListener('pointermove', e => { if (e.pointerId === stickId) updateStick(e) })
    const endStick = e => {
      if (e.pointerId !== stickId) return
      stickId = null; this.touch.moveX = 0; this.touch.moveY = 0
      knob.style.transform = ''
    }
    stick.addEventListener('pointerup', endStick)
    stick.addEventListener('pointercancel', endStick)

    const lookZone = this.canvas
    lookZone.addEventListener('pointerdown', e => {
      if (!this.isTouchDevice() || this.state !== 'playing') return
      if (e.clientX < innerWidth * .42) return
      this.touch.lookId = e.pointerId; this.touch.lastX = e.clientX; this.touch.lastY = e.clientY; this.touch.dragging = true
      lookZone.setPointerCapture?.(e.pointerId)
    })
    lookZone.addEventListener('pointermove', e => {
      if (!this.touch.dragging || e.pointerId !== this.touch.lookId) return
      const dx = e.clientX - this.touch.lastX
      const dy = e.clientY - this.touch.lastY
      this.yaw -= dx * .006 * (this.settings.sensitivity / 100)
      this.pitch = clamp(this.pitch + dy * .0045, -.18, .82)
      this.touch.lastX = e.clientX; this.touch.lastY = e.clientY
    })
    const endLook = e => {
      if (e.pointerId !== this.touch.lookId) return
      this.touch.dragging = false; this.touch.lookId = null
    }
    lookZone.addEventListener('pointerup', endLook)
    lookZone.addEventListener('pointercancel', endLook)

    document.querySelectorAll('[data-touch]').forEach(btn => {
      btn.addEventListener('pointerdown', e => {
        e.preventDefault()
        if (this.state !== 'playing') return
        const a = btn.dataset.touch
        if (a === 'attack') this.tryAttack('light')
        if (a === 'heavy') this.tryAttack('heavy')
        if (a === 'dodge') this.tryDodge()
        if (a === 'execute') this.tryExecute()
        if (a === 'block') this.startBlock()
      })
      if (btn.dataset.touch === 'block') {
        const end = () => this.endBlock()
        btn.addEventListener('pointerup', end)
        btn.addEventListener('pointercancel', end)
      }
    })
  }

  togglePause() {
    if (this.state === 'playing') this.pause()
    else if (this.state === 'paused') this.resume()
    else if (this.ui.currentOverlay && this.ui.currentOverlay !== 'boons') {
      if (this.state === 'title') this.ui.closeAllOverlays()
      else if (this.ui.currentOverlay === 'settings') this.closeSettings()
    }
  }

  pause() {
    if (this.state !== 'playing') return
    this.state = 'paused'
    this.ui.setPauseStats(this.wave, this.kills, this.score)
    this.ui.showPause(true)
    this.endBlock()
    if (document.pointerLockElement) document.exitPointerLock()
  }

  resume() {
    if (this.state !== 'paused') return
    this.state = 'playing'
    this.ui.showPause(false)
    this.requestLock()
  }

  openSettings() {
    if (this.state === 'playing') this.pause()
    this.settingsReturn = this.ui.currentOverlay
    this.ui.closeOverlay('pause')
    this.ui.openOverlay('settings')
  }

  closeSettings() {
    this.ui.closeOverlay('settings')
    if (this.state === 'paused') this.ui.openOverlay('pause')
    if (this.state === 'title') this.ui.showTitle()
  }

  openArmory(context = 'title') {
    if (this.state === 'playing') this.pause()
    this.armoryContext = context
    this.ui.showArmory(this.meta, { weapon: this.meta.weapon, armor: this.meta.armor })
  }

  armoryAction(tab, id) {
    const list = tab === 'weapons' ? WEAPONS : ARMORS
    const item = list.find(i => i.id === id)
    if (!item) return
    const unlockedKey = tab === 'weapons' ? 'unlockedWeapons' : 'unlockedArmor'
    const equipKey = tab === 'weapons' ? 'weapon' : 'armor'
    let unlocked = this.meta[unlockedKey]
    if (!unlocked.includes(id)) {
      if (this.meta.marks < item.cost) return
      this.meta.marks -= item.cost
      this.meta[unlockedKey] = [...unlocked, id]
      this.audio.unlock()
      this.ui.toast(`${item.name} UNLOCKED`, 'gold')
    }
    this.meta[equipKey] = id
    this.saveMeta()
    this.ui.updateTitleLoadout(this.meta)
    if (tab === 'weapons') { this.weapon = getWeapon(id); this.meta.weapon = id }
    else { this.armor = getArmor(id); this.meta.armor = id }
    this.ui.renderArmory(this.meta, { weapon: this.meta.weapon, armor: this.meta.armor })
    this.ui.toast(`${item.name} EQUIPPED`, 'gold')
    if (this.state === 'title') this.refreshTitlePlayer()
  }

  refreshTitlePlayer() {
    this.spawnPlayer()
    this.player.root.position.set(0, 0, 3.1)
    this.player.root.rotation.y = .16
    this.ui.updateTitleLoadout(this.meta)
  }

  saveMeta() {
    try { localStorage.setItem(SAVE_KEY, JSON.stringify(this.meta)) } catch {}
  }

  saveSettings() {
    try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(this.settings)) } catch {}
  }

  changeSetting(key, value) {
    this.settings[key] = value
    if (key === 'volume') this.audio.setVolume(value / 100)
    if (key === 'scale') { this.applyPixelRatio(); this.resize() }
    if (key === 'shake' || key === 'motion') this.shakeEnabled = this.settings.shake && !this.settings.motion
    this.saveSettings()
  }

  startRun() {
    this.audio.start()
    this.ui.closeAllOverlays()
    this.ui.hideTitle()
    this.ui.enterGame()
    this.state = 'playing'
    this.endBlock()
    this.clearEnemies()
    this.resetRunData()
    this.spawnPlayer()
    this.player.root.position.set(0, 0, 8)
    this.player.root.rotation.y = Math.PI
    this.meta.runs = (this.meta.runs || 0) + 1
    this.themeIndex = 0
    this.arena.build(0)
    this.yaw = 0
    this.pitch = .19
    this.cameraDist = 4.8
    this.intro = 1
    this.startWave(1)
    this.requestLock()
    this.ui.toast('THE CROWD REMEMBERS YOU', 'blood')
    setTimeout(() => this.ui.showAnnouncement('THE GATE OPENS', 'WAVE I', 'SURVIVE THE CROWD’S HUNGER', false, 2600), 650)
  }

  clearEnemies() {
    for (const e of this.enemies) {
      e.char.onArmorBreak = null
      e.char.onDecapitate = null
      e.char.dispose()
    }
    this.enemies = []
    this.ui.clearEnemyBars()
  }

  startWave(wave) {
    this.wave = wave
    this.waveActive = true
    this.waveClearTimer = -1
    this.spawnTimer = 0
    this.attackStep = 0
    this.chain = 1
    this.chainTimer = 0
    this.combo = 0
    this.rage = Math.min(100, this.rage + this.waveRage)
    const theme = Math.floor((wave - 1) / 4) % 3
    if (theme !== this.themeIndex) {
      this.themeIndex = theme
      this.arena.build(theme)
      this.ui.showAnnouncement('THE GROUND SHIFTS', ARENAS[theme].name, 'A NEW TRIAL BEGINS', false, 3000)
    }
    const boss = wave % 5 === 0
    this.activeLimit = boss ? 2 : Math.min(4, 1 + Math.ceil(wave / 2.2))
    this.spawnQueue = this.composeWave(wave, boss)
    this.ui.setWave(wave, ARENAS[this.themeIndex].name, boss ? 'BREAK THE CHAMPION' : ARENAS[this.themeIndex].sub, boss)
    this.audio.waveHorn(boss)
    this.arena.excite(.35)
    if (boss) this.ui.showAnnouncement('CHAMPION OF THE PIT', ENEMY_TYPES.champion.name, 'NO MERCY IS GIVEN', true, 3400)
    else this.ui.showAnnouncement('THE CROWD RISES', `WAVE ${roman(wave)}`, 'SURVIVE', false, 2200)
  }

  composeWave(wave, boss) {
    const q = []
    if (boss) {
      q.push('champion')
      if (wave >= 10) q.push('knight')
      if (wave >= 15) q.push('berserker')
      if (wave >= 20) q.push('knight')
      return q
    }
    const count = Math.min(9, 2 + Math.floor((wave - 1) * .58))
    for (let i = 0; i < count; i++) {
      let type = 'gladiator'
      const r = Math.random()
      if (wave >= 9) type = r < .35 ? 'gladiator' : r < .68 ? 'knight' : 'berserker'
      else if (wave >= 6) type = r < .45 ? 'gladiator' : r < .72 ? 'knight' : 'berserker'
      else if (wave >= 3) type = r < .66 ? 'gladiator' : 'berserker'
      else if (wave >= 2) type = r < .85 ? 'gladiator' : 'berserker'
      q.push(type)
    }
    return q
  }

  updateSpawns(dt) {
    if (!this.waveActive || this.spawnQueue.length === 0) return
    const alive = this.enemies.filter(e => !e.char.dead).length
    if (alive >= this.activeLimit) return
    this.spawnTimer -= dt
    if (this.spawnTimer > 0) return
    const type = this.spawnQueue.shift()
    this.spawnEnemy(type)
    this.spawnTimer = this.spawnQueue.length ? rand(.6, 1.1) : 0
  }

  spawnEnemy(type) {
    const def = ENEMY_TYPES[type]
    const boss = type === 'champion'
    const waveScale = 1 + (this.wave - 1) * .055
    const health = Math.round(def.health * (boss ? 1 + Math.floor(this.wave / 5) * .1 : waveScale))
    const char = new Character(this.scene, { type, health, armor: def.armor, weaponData: { kind: def.weapon } })
    char.def = def
    char.maxHealth = health
    char.health = health
    char.speed = def.speed * (1 + Math.min(.2, (this.wave - 1) * .008))
    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
    const right = new THREE.Vector3(-Math.cos(this.yaw), 0, Math.sin(this.yaw))
    const spawnDist = boss ? 16 : rand(11.5, 15.5)
    let pos = this.player.root.position.clone()
      .addScaledVector(forward, spawnDist)
      .addScaledVector(right, boss ? 0 : rand(-6, 6))
    pos.y = 0
    this.arena.clampToArena(pos, 1.2)
    char.root.position.copy(pos)
    char.root.rotation.y = Math.atan2(this.player.root.position.x - pos.x, this.player.root.position.z - pos.z)
    const e = {
      id: this.enemyId++, type, def, char, boss,
      state: 'approach', cooldown: rand(.9, 1.8), blockCd: rand(.8, 2), blockTimer: 0, guard: boss ? 5 : def.shield ? 2 : 0,
      strafe: chance(.5) ? 1 : -1, decision: 0, removeTimer: 0, hitFlash: 0, knock: new THREE.Vector3(),
      staggerResist: boss ? 1 : 0, dyingAwarded: false
    }
    char.onArmorBreak = piece => this.onEnemyArmorBreak(e, piece)
    char.onDecapitate = () => {
      const p = new THREE.Vector3(); char.getHeadPosition(p); p.y -= .3
      this.effects.spawnHead(p, 0x8d624d, def.boss ? 0x333334 : 0x5c5150)
    }
    this.enemies.push(e)
    if (boss) {
      this.ui.setBoss(e)
      this.arena.excite(.7)
      this.audio.roar(true)
      this.effects.dust(char.root.position, 18, 0x8e735c, 1.6)
    } else {
      this.effects.dust(char.root.position, 9, 0x8a7258, 1)
    }
    return e
  }

  updatePlayer(dt) {
    const c = this.player
    if (this.state === 'dead') { c.update(dt); return }
    if (this.execution) { c.update(dt); return }
    if (this.attackCooldown > 0) this.attackCooldown -= dt
    if (this.playerInvuln > 0) this.playerInvuln -= dt
    if (this.hazardCooldown > 0) this.hazardCooldown -= dt
    if (this.chainTimer > 0) { this.chainTimer -= dt; if (this.chainTimer <= 0) { this.chain = 1; this.combo = 0 } }
    if (this.comboWindow > 0) { this.comboWindow -= dt; if (this.comboWindow <= 0) this.attackStep = 0 }

    const canMove = c.state !== 'attack' && c.state !== 'hit' && c.state !== 'dead' && !this.blocking
    let move = new THREE.Vector3()
    if (canMove) {
      const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
      const right = new THREE.Vector3(-Math.cos(this.yaw), 0, Math.sin(this.yaw))
      if (this.keys.forward) move.add(forward)
      if (this.keys.back) move.sub(forward)
      if (this.keys.right) move.add(right)
      if (this.keys.left) move.sub(right)
      if (this.touch.moveX || this.touch.moveY) {
        move.addScaledVector(right, this.touch.moveX)
        move.addScaledVector(forward, -this.touch.moveY)
      }
      if (move.lengthSq() > 1) move.normalize()
    }
    const sprinting = this.keys.sprint && move.lengthSq() > .01 && this.stamina > 1
    let speed = this.player.speed * this.moveSpeedMul * (sprinting ? 1.32 : 1)
    if (this.blocking) speed *= .3
    if (c.state === 'dodge') speed = this.player.speed * 2.35 * this.dodgeMul
    if (c.state === 'hit') speed = 0
    if (sprinting) {
      this.stamina = Math.max(0, this.stamina - 12 * dt)
      this.staminaDelay = .6
    }
    if (this.blocking) {
      this.stamina = Math.max(0, this.stamina - 5 * dt)
      this.staminaDelay = .4
      if (this.stamina <= 0) this.breakGuard()
    }
    if (move.lengthSq() > .01) {
      c.root.position.addScaledVector(move, speed * dt)
      if (canMove || c.state === 'dodge') {
        const desired = Math.atan2(move.x, move.z)
        c.root.rotation.y = dampAngle(c.root.rotation.y, desired, c.state === 'dodge' ? 20 : 12, dt)
      }
    }
    c.root.position.addScaledVector(this.playerKnockback, dt)
    this.playerKnockback.multiplyScalar(Math.max(0, 1 - dt * 12))
    this.arena.clampToArena(c.root.position, .55)
    c.speedActual = move.lengthSq() > .01 ? speed : 0
    if (c.state === 'dodge' && c.stateTime > .39) { c.state = 'idle'; c.stateTime = 0 }
    if (c.state === 'dodge') this.playerInvuln = Math.max(this.playerInvuln, .03)

    // stamina recovery
    this.staminaDelay = Math.max(0, this.staminaDelay - dt)
    if (this.staminaDelay <= 0 && !sprinting && !this.blocking) {
      this.stamina = Math.min(this.maxStamina, this.stamina + this.staminaRegen * dt)
    }
    if (c.state === 'attack') {
      // minor forward momentum
      const forward = new THREE.Vector3(Math.sin(c.root.rotation.y), 0, Math.cos(c.root.rotation.y))
      c.root.position.addScaledVector(forward, dt * (this.player.attackType === 'heavy' ? .8 : 1.2))
      this.arena.clampToArena(c.root.position, .55)
    }
    c.update(dt)
    if (c.events.swing) {
      c.events.swing = false
      this.audio.swing(c.attackType === 'heavy' ? 1.25 : .9)
      const ip = c.root.position.clone()
      this.effects.slash(ip, c.root.rotation.y, c.attackType === 'heavy')
    }
    if (c.events.hit) {
      c.events.hit = false
      this.resolvePlayerAttack()
    }
    if (this.attackBuffer && this.attackBuffer.time > 0) {
      this.attackBuffer.time -= dt
      if (c.state === 'idle' && this.attackCooldown <= 0) {
        const t = this.attackBuffer.type
        this.attackBuffer = null
        this.tryAttack(t)
      } else if (this.attackBuffer.time <= 0) this.attackBuffer = null
    }
    if (c.state === 'idle') this.playerInvuln = Math.max(0, this.playerInvuln - dt * 10)
    if (this.stamina <= .5) this.blockBroken = true

    // footsteps
    if (c.speedActual > .3 && c.state === 'idle') {
      this.stepTimer = (this.stepTimer || 0) + dt * c.speedActual
      if (this.stepTimer > 2.1) {
        this.stepTimer = 0
        this.audio.footstep(this.themeIndex === 0 ? 0 : 1)
      }
    }
  }

  tryAttack(type) {
    if (this.state !== 'playing' || this.execution || this.player.dead) return
    const c = this.player
    if (c.state === 'hit' || c.state === 'dodge') return
    if (c.state === 'attack') { this.attackBuffer = { type, time: .38 }; return }
    if (this.attackCooldown > 0) return
    if (this.stamina < (type === 'heavy' ? 20 : 9)) {
      this.ui.toast('STAMINA SPENT', 'blood')
      this.audio.ui()
      return
    }
    const heavy = type === 'heavy'
    const cost = (heavy ? this.weapon.stamina * 1.65 : this.weapon.stamina) * this.staminaCostMul
    if (this.stamina < cost) { this.ui.toast('STAMINA SPENT', 'blood'); return }
    this.stamina -= cost
    this.staminaDelay = .9
    this.blocking = false
    const duration = (heavy ? .78 : .43 + (this.attackStep % 2) * .015) / this.weapon.speed
    this.player.attackType = heavy ? 'heavy' : 'light'
    c.startAttack(this.player.attackType, duration)
    // face the closest target or camera forward
    const target = this.closestEnemyInFront(4.7, 1.25)
    if (target) {
      const d = target.char.root.position.clone().sub(c.root.position)
      c.root.rotation.y = Math.atan2(d.x, d.z)
    } else {
      c.root.rotation.y = Math.atan2(-Math.sin(this.yaw), -Math.cos(this.yaw))
    }
    if (!heavy) {
      this.attackStep++
      this.comboWindow = 1.05
      this.attackCooldown = .08
    } else {
      this.attackStep = 0
      this.attackCooldown = .25
    }
  }

  closestEnemyInFront(maxDist = 4.5, maxAngle = 1.2) {
    const c = this.player
    let best = null, bestScore = Infinity
    for (const e of this.enemies) {
      if (e.char.dead || e.removed) continue
      const d = e.char.root.position.clone().sub(c.root.position)
      const dist = d.length()
      if (dist > maxDist) continue
      const ang = Math.abs(shortestAngle(c.root.rotation.y, Math.atan2(d.x, d.z)))
      if (ang > maxAngle) continue
      const score = dist + ang * 1.6
      if (score < bestScore) { bestScore = score; best = e }
    }
    return best
  }

  resolvePlayerAttack() {
    const c = this.player
    const heavy = c.attackType === 'heavy'
    const range = this.weapon.reach + (heavy ? .35 : .2)
    const facing = c.root.rotation.y
    const hits = []
    for (const e of this.enemies) {
      if (e.char.dead || e.removed) continue
      const d = e.char.root.position.clone().sub(c.root.position)
      const dist = Math.hypot(d.x, d.z)
      if (dist > range + .35) continue
      const ang = Math.abs(shortestAngle(facing, Math.atan2(d.x, d.z)))
      if (ang > (heavy ? .82 : 1.08)) continue
      hits.push({ e, dist, ang })
    }
    if (!hits.length) {
      this.audio.swing(.7)
      return
    }
    const base = heavy ? this.weapon.heavy : this.weapon.damage
    for (const { e } of hits) {
      const dir = e.char.root.position.clone().sub(c.root.position).normalize()
      const facingPlayer = Math.abs(shortestAngle(e.char.root.rotation.y, Math.atan2(-dir.x, -dir.z))) < 1.25
      if ((e.char.state === 'block' || e.blockTimer > 0) && facingPlayer) {
        e.guard -= heavy ? 2 : 1
        this.effects.sparksBurst(e.char.getChestPosition(), dir.clone().negate(), heavy ? 26 : 14, heavy ? 1.4 : 1)
        this.audio.block()
        this.ui.hitMarker(heavy)
        this.effects.shake(heavy ? .3 : .12)
        this.hitstop = Math.max(this.hitstop, .035)
        this.chain = Math.max(1, this.chain * .75)
        if (e.guard <= 0) {
          e.blockTimer = 0
          e.char.stagger(1.4)
          e.char.shieldBroken = true
          if (e.char.shield) {
            e.char.shield.visible = false
            this.effects.spawnDebris(e.char.root.position.clone().add(new THREE.Vector3(0, 1.2, 0)), 0x4a281c, .2)
          }
          this.ui.toast('GUARD BROKEN', 'gold')
          this.audio.parry()
          e.guard = 2
        }
        continue
      }
      let dmg = base * this.damageMul * rand(.93, 1.07)
      if (e.char.state === 'hit') dmg *= 1.12
      const result = e.char.takeHit(dmg, {
        heavy, breakPower: this.weapon.break * this.breakMul,
        side: Math.sign(dir.x) || 1,
        ignoreArmor: false
      })
      if (!result) continue
      const chest = e.char.getChestPosition()
      const bloodAmount = Math.round((heavy ? 34 : 20) * (this.settings.gore / 2 + .15))
      this.effects.bloodBurst(chest, dir, bloodAmount, heavy ? 1.25 : .85)
      this.effects.sparksBurst(chest, dir.clone().negate(), heavy ? 14 : 6, .7)
      this.audio.hit(heavy ? 1.45 : .9, e.char.armor > 0)
      this.audio.flesh(heavy ? 1.4 : .8)
      this.ui.hitMarker(heavy)
      this.ui.flashBlood()
      this.hitstop = Math.max(this.hitstop, heavy ? .085 : .045)
      if (this.shakeEnabled) this.effects.shake(heavy ? .48 : .2)
      this.effects.floatText(chest, `${Math.round(result.damage)}`, result.broken ? 'crit' : '')
      if (result.broken) this.ui.toast(`${result.broken.label} SHATTERED`, 'gold')
      if (result.damage > 0 && this.lifesteal > 0) this.heal(result.damage * this.lifesteal, true)
      this.rage = Math.min(100, this.rage + (heavy ? 13 : 6.5))
      this.chain = Math.min(4, this.chain + (heavy ? .35 : .22))
      this.chainTimer = 1.7
      this.combo++
      this.score += Math.round(result.damage * 8 * this.chain)
      if (result.killed) this.onEnemyKilled(e, heavy)
      else if (e.char.armor > 0) e.char.addWound()
    }
  }

  onEnemyArmorBreak(e, piece) {
    const pos = new THREE.Vector3()
    piece.mesh.getWorldPosition(pos)
    this.effects.spawnDebris(pos, piece.mesh.material?.color?.getHex?.() || 0x5c5c5c, .18, null, 'metal')
    if (this.settings.gore > 0) this.effects.bloodBurst(pos, new THREE.Vector3(0, .2, 0), Math.round(7 * this.settings.gore), .7)
    this.audio.hit(1.1, true)
  }

  onPlayerArmorBreak(piece) {
    const pos = new THREE.Vector3()
    piece.mesh.getWorldPosition(pos)
    this.effects.spawnDebris(pos, 0x4a4e4d, .16, null, 'metal')
    this.ui.toast(`${piece.label} SHATTERED`, 'blood')
  }

  onEnemyKilled(e, heavy = false) {
    if (e.dyingAwarded) return
    e.dyingAwarded = true
    this.kills++
    this.score += Math.round(e.def.score * this.chain)
    const marks = Math.round(e.def.marks * (1 + this.wave * .035))
    this.runMarks += marks
    this.rage = Math.min(100, this.rage + (e.boss ? 30 : 9))
    this.audio.death()
    this.arena.excite(e.boss ? 1 : .28)
    if (e.boss) {
      this.ui.setBoss(null)
      this.ui.showAnnouncement('THE CHAMPION FALLS', e.def.name, 'THE CROWD HAS A NEW GOD', true, 3400)
      this.audio.waveHorn(true)
      this.effects.sparksBurst(e.char.getChestPosition(), new THREE.Vector3(0, 1, 0), 60, 1.8)
    }
    if ((heavy || e.boss) && this.settings.gore >= 1 && chance(e.boss ? .75 : .22)) {
      e.char.decapitate()
    }
    if (this.settings.gore >= 1) {
      const chest = e.char.getChestPosition()
      this.effects.bloodBurst(chest, new THREE.Vector3(rand(-.4, .4), 1, rand(-.4, .4)), 20, .8)
    }
    this.ui.toast(`${e.def.name} BROKEN`, e.boss ? 'gold' : '')
    this.effects.floatText(e.char.getHeadPosition(), `+${marks}`, 'heal')
  }

  startBlock() {
    if (this.state !== 'playing' || this.execution || this.player.dead) return
    if (this.stamina < 6 || this.player.state === 'hit' || this.player.state === 'attack') return
    this.blocking = true
    this.blockStart = this.realTime
    this.player.setState('block', 0)
  }

  endBlock() {
    this.blocking = false
    if (this.player && this.player.state === 'block') { this.player.state = 'idle'; this.player.stateTime = 0 }
  }

  breakGuard() {
    if (!this.blocking) return
    this.endBlock()
    this.player.setState('hit', 0)
    this.player.stagger(1.1)
    this.player.staggered = true
    this.audio.hurt()
    this.ui.toast('GUARD BROKEN', 'blood')
    this.effects.shake(.35)
    this.stamina = 0
  }

  tryDodge() {
    if (this.state !== 'playing' || this.execution || this.player.dead) return
    const c = this.player
    if (c.state === 'attack' || c.state === 'hit' || c.state === 'dodge') return
    const cost = 22 * this.staminaCostMul
    if (this.stamina < cost) { this.ui.toast('STAMINA SPENT', 'blood'); return }
    this.stamina -= cost
    this.staminaDelay = .7
    this.endBlock()
    c.setState('dodge', 0)
    c.attackType = 'light'
    this.playerInvuln = .33
    const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
    const right = new THREE.Vector3(-Math.cos(this.yaw), 0, Math.sin(this.yaw))
    let dir = new THREE.Vector3()
    if (this.keys.forward) dir.add(forward)
    if (this.keys.back) dir.sub(forward)
    if (this.keys.right) dir.add(right)
    if (this.keys.left) dir.sub(right)
    if (this.touch.moveX || this.touch.moveY) { dir.addScaledVector(right, this.touch.moveX); dir.addScaledVector(forward, -this.touch.moveY) }
    if (!dir.lengthSq()) dir.copy(forward).negate()
    dir.normalize()
    const dest = c.root.position.clone().addScaledVector(dir, 2.7 * this.dodgeMul)
    this.arena.clampToArena(dest, .6)
    c.root.position.copy(dest)
    c.root.rotation.y = Math.atan2(dir.x, dir.z)
    this.effects.dust(c.root.position, 12, 0x8a7258, 1.2)
    this.audio.noiseBurst({ duration: .22, gain: .07, freq: 900, endFreq: 200, q: .6, type: 'lowpass' })
  }

  tryExecute() {
    if (this.state !== 'playing' || this.execution || this.player.dead) return
    if (this.rage < this.executeCost) { this.ui.toast('BLOODLUST TOO LOW', 'blood'); return }
    let best = null, bestDist = 3.4
    for (const e of this.enemies) {
      if (e.char.dead || e.removed) continue
      const ratio = e.char.health / e.char.maxHealth
      if (ratio > (e.boss ? .16 : .34)) continue
      const dist = e.char.root.position.distanceTo(this.player.root.position)
      if (dist < bestDist) { bestDist = dist; best = e }
    }
    if (!best) { this.ui.toast('NO BROKEN FOE', ''); return }
    this.rage -= this.executeCost
    this.execution = { enemy: best, time: 0, killed: false, start: this.player.root.position.clone() }
    this.state = 'executing'
    this.timeScale = .3
    this.ui.showSlowmo(true)
    this.endBlock()
    this.attackBuffer = null
    best.char.stagger(3)
    best.char.health = Math.max(1, best.char.health)
    this.audio.execute()
    this.audio.heartbeat()
    this.effects.shake(.2)
    const d = best.char.root.position.clone().sub(this.player.root.position)
    this.player.root.rotation.y = Math.atan2(d.x, d.z)
    this.player.setState('execute', 0)
  }

  updateExecution(dt) {
    const ex = this.execution
    if (!ex) return
    ex.time += dt
    const target = ex.enemy
    if (!ex.killed) {
      const d = target.char.root.position.clone().sub(this.player.root.position)
      const dist = Math.hypot(d.x, d.z)
      if (dist > 1.6) {
        this.player.root.position.addScaledVector(d.normalize(), Math.min(dist - 1.6, dt * 4.5))
        this.arena.clampToArena(this.player.root.position, .6)
      }
      this.player.root.rotation.y = dampAngle(this.player.root.rotation.y, Math.atan2(d.x, d.z), 12, dt)
      this.player.update(dt * .55)
      target.char.update(dt * .45)
      if (ex.time > .85) {
        ex.killed = true
        target.char.health = 1
        target.char.takeHit(99999, { heavy: true, ignoreArmor: true, side: 1 })
        target.char.die({ decapitate: true })
        this.onEnemyKilled(target, true)
        this.effects.bloodBurst(target.char.getChestPosition(), new THREE.Vector3(0, 1.2, 0), 95, 1.8)
        this.effects.sparksBurst(target.char.getChestPosition(), new THREE.Vector3(0, 1, 0), 30, 1.3)
        this.effects.shake(.65)
        this.audio.hit(1.8, true)
        this.audio.flesh(1.8)
        this.heal(this.executeHeal)
        this.score += 450
        this.arena.excite(1)
        this.ui.hitMarker(true)
        this.ui.flashBlood()
        this.ui.showAnnouncement('A LIFE GIVEN', 'REQUIEM', 'THE SAND DRINKS DEEP', true, 1700)
      }
    } else {
      target.char.update(dt * .45)
      this.player.update(dt * .3)
    }
    if (ex.time > 1.72) {
      this.execution = null
      this.state = 'playing'
      this.timeScale = 1
      this.ui.showSlowmo(false)
      this.player.state = 'idle'
      this.player.stateTime = 0
      this.attackCooldown = .32
    }
  }

  updateEnemies(dt) {
    const playerPos = this.player.root.position
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i]
      const c = e.char
      if (c.dead) {
        c.update(dt)
        e.removeTimer += dt
        if (e.removeTimer > 5.2) {
          c.dispose()
          this.enemies.splice(i, 1)
          if (e.boss) this.ui.setBoss(null)
        }
        continue
      }
      const d = playerPos.clone().sub(c.root.position)
      const dist = Math.hypot(d.x, d.z)
      e.cooldown -= dt
      e.blockCd -= dt
      if (e.blockTimer > 0) e.blockTimer -= dt
      const facingPlayer = Math.abs(shortestAngle(c.root.rotation.y, Math.atan2(d.x, d.z))) < 1.35
      const boss = e.boss
      const def = e.def
      const ideal = def.attackRange * .78

      // Raise guard when the player commits to an attack.
      if (!boss && def.shield && e.blockCd <= 0 && e.blockTimer <= 0 && c.state === 'idle' && dist < 4.4 && this.player.state === 'attack' && facingPlayer && this.settings.gore >= 0 && chance(dt * 3.1)) {
        c.setState('block', 0)
        e.blockTimer = .58
        e.blockCd = rand(1.3, 2.5)
      }
      if (e.blockTimer <= 0 && c.state === 'block') { c.state = 'idle'; c.stateTime = 0 }

      if (c.state === 'idle' || c.state === 'dodge') {
        let move = new THREE.Vector3()
        if (!c.blocking && dist > ideal + .15) {
          move.copy(d).normalize()
          if (e.strafe) move.addScaledVector(new THREE.Vector3(-d.z, 0, d.x).normalize(), .2)
        } else if (dist < ideal - .55) {
          move.copy(d).normalize().multiplyScalar(-.65)
        } else {
          move.set(-d.z, 0, d.x).normalize().multiplyScalar(e.strafe * .45)
        }
        // separation
        for (const other of this.enemies) {
          if (other === e || other.char.dead) continue
          const od = c.root.position.clone().sub(other.char.root.position)
          const odist = od.length()
          if (odist < 1.35 && odist > .01) move.addScaledVector(od.normalize(), (1.35 - odist) * 1.5)
        }
        if (move.lengthSq() > 1) move.normalize()
        c.speedActual = move.length() * c.speed * (c.state === 'dodge' ? 1.4 : 1)
        c.root.position.addScaledVector(move, c.speedActual * dt)
        const desired = Math.atan2(d.x, d.z)
        c.root.rotation.y = dampAngle(c.root.rotation.y, desired, 6 + def.aggressive * 3, dt)
        // attack decision
        if (dist < def.attackRange && e.cooldown <= 0 && facingPlayer && !c.blocking) {
          const pressure = def.aggressive * (boss ? 1.1 : 1) * (this.wave > 8 ? 1.12 : 1)
          if (chance(dt * (1.7 + pressure * 2.2))) {
            c.startAttack(boss && chance(.28) ? 'heavy' : 'light', (boss && c.attackType === 'heavy' ? 1.12 : def.windup + .22))
            e.cooldown = rand(def.windup + def.recover, def.windup + def.recover + 1.2) * (boss ? .72 : 1)
            e.attackAngle = Math.atan2(d.x, d.z)
            c.root.rotation.y = e.attackAngle
          }
        }
      } else {
        c.speedActual = 0
        if (c.state !== 'attack' && c.state !== 'hit' && c.state !== 'block') c.root.rotation.y = dampAngle(c.root.rotation.y, Math.atan2(d.x, d.z), 4, dt)
      }
      c.root.position.addScaledVector(e.knock, dt)
      e.knock.multiplyScalar(Math.max(0, 1 - dt * 7))
      this.arena.clampToArena(c.root.position, .75)
      c.update(dt)
      if (c.events.swing) {
        c.events.swing = false
        this.audio.swing(.7)
      }
      if (c.events.hit) {
        c.events.hit = false
        const hitDist = c.root.position.distanceTo(playerPos)
        if (hitDist < def.attackRange + .85 && facingPlayer) {
          const heavy = c.attackType === 'heavy'
          this.enemyHitPlayer(e, def.damage * (boss ? (heavy ? 1.5 : 1) : 1), heavy)
          if (boss && heavy) {
            this.effects.sparksBurst(playerPos.clone().setY(.2), new THREE.Vector3(0, 1, 0), 35, 1.5)
            this.effects.shake(.5)
            if (this.playerInvuln <= 0) this.damagePlayer(8, e, true)
          }
        } else {
          this.audio.swing(.5)
        }
      }
      // telegraph glint
      if (c.state === 'attack' && c.attackProgress < .5 && Math.random() < dt * 10) {
        this.effects.embers(c.getWeaponTip(), 1, boss ? 0xff3014 : 0xff9b5b)
      }
    }
  }

  enemyHitPlayer(e, damage, heavy) {
    if (this.state !== 'playing' || this.player.dead) return
    if (this.playerInvuln > 0) {
      if (chance(.4)) this.effects.dust(this.player.root.position, 6, 0x8f7b63, .8)
      return
    }
    const toEnemy = e.char.root.position.clone().sub(this.player.root.position).normalize()
    const playerForward = new THREE.Vector3(Math.sin(this.player.root.rotation.y), 0, Math.cos(this.player.root.rotation.y))
    const facing = playerForward.dot(toEnemy) > .12
    if (this.blocking && facing) {
      if (this.realTime - this.blockStart < .25) {
        this.parry(e)
        return
      }
      const staminaCost = damage * 1.6
      this.stamina = Math.max(0, this.stamina - staminaCost)
      this.staminaDelay = .8
      const chip = damage * .14 * this.damageTakenMul
      this.damagePlayer(chip, e, true)
      this.effects.sparksBurst(this.player.root.position.clone().setY(1.25), toEnemy.clone().negate(), 22, 1.2)
      this.audio.block()
      this.ui.hitMarker(false)
      if (this.shakeEnabled) this.effects.shake(.18)
      if (this.stamina <= 0) this.breakGuard()
      return
    }
    this.damagePlayer(damage, e, heavy)
  }

  parry(e) {
    this.audio.parry()
    this.ui.flashParry()
    this.ui.showAnnouncement('PARRY', 'PERFECT', '', false, 900)
    this.effects.sparksBurst(this.player.root.position.clone().setY(1.3), new THREE.Vector3(0, 1, 0), 34, 1.6)
    this.effects.shake(.24)
    this.effects.floatText(e.char.getChestPosition(), 'PARRY', 'block')
    e.char.stagger(1.45)
    this.rage = Math.min(100, this.rage + 16)
    this.score += 180
    this.chain = Math.min(4, this.chain + .4)
    this.stamina = Math.min(this.maxStamina, this.stamina + 12)
    this.playerInvuln = .35
    this.slowmoTimer = .3
    this.arena.excite(.45)
    this.ui.setReticle(true)
  }

  damagePlayer(amount, source, heavy = false) {
    if (this.player.dead) return
    const dmg = Math.max(1, amount * (1 - this.armor.defense) * this.damageTakenMul)
    const result = this.player.takeHit(dmg, { heavy, side: chance(.5) ? 1 : -1, ignoreArmor: false })
    if (!result) return
    this.stamina = Math.max(0, this.stamina - (heavy ? 20 : 11))
    this.staminaDelay = 1.1
    this.lastDamageTime = this.realTime
    this.ui.flashDamage()
    if (this.settings.gore > 1) this.ui.flashBlood()
    if (this.shakeEnabled) this.effects.shake(heavy ? .68 : .38)
    this.hitstop = Math.max(this.hitstop, heavy ? .08 : .035)
    this.audio.hurt()
    this.effects.bloodBurst(this.player.root.position.clone().setY(1.25), new THREE.Vector3(0, .4, 0), 10, .6)
    if (source) {
      const dir = this.player.root.position.clone().sub(source.char.root.position).normalize()
      this.playerKnockback.addScaledVector(dir, heavy ? 5 : 2.4)
    }
    if (this.player.health <= 0) this.playerDied(source)
  }

  heal(amount, silent = false) {
    if (!this.player || this.player.dead) return
    const before = this.player.health
    this.player.health = Math.min(this.maxHealth, this.player.health + amount)
    const gained = this.player.health - before
    if (!silent && gained > 0) this.effects.floatText(this.player.root.position.clone().setY(2), `+${Math.round(gained)}`, 'heal')
  }

  playerDied(source) {
    if (this.state === 'dead') return
    this.state = 'dead'
    this.player.die({ side: chance(.5) ? 1 : -1 })
    this.player.health = 0
    this.deathTimer = 0
    this.deathShown = false
    this.timeScale = .28
    this.endBlock()
    this.execution = null
    this.audio.death()
    this.audio.hurt()
    this.ui.flashBlood()
    this.ui.showSlowmo(true)
    this.effects.shake(.7)
    this.effects.bloodBurst(this.player.root.position.clone().setY(1.2), new THREE.Vector3(0, .5, 0), 40, 1.2)
    this.arena.excite(.8)
    this.meta.bestWave = Math.max(this.meta.bestWave || 0, this.wave)
    this.meta.kills = (this.meta.kills || 0) + this.kills
    this.meta.renown = (this.meta.renown || 0) + Math.round(this.score * .07) + this.wave * 30
    this.meta.marks += this.runMarks
    this.saveMeta()
  }

  updateWave(dt) {
    if (!this.waveActive) return
    const alive = this.enemies.filter(e => !e.char.dead && !e.removed).length
    if (this.spawnQueue.length === 0 && alive === 0 && this.state === 'playing') {
      this.waveActive = false
      this.waveClearTimer = 2.1
      const reward = Math.round(75 + this.wave * 28 + (this.wave % 5 === 0 ? 220 : 0))
      this.runMarks += reward
      this.score += this.wave * 120
      this.boonChoices = this.rollBoons()
      this.ui.showAnnouncement('THE SAND FALLS STILL', `WAVE ${roman(this.wave)} CLEARED`, `+${formatNumber(reward)} BLOODMARKS`, false, 2600)
      this.audio.waveHorn(false)
      this.arena.excite(1)
      this.waveReward = reward
    }
    if (this.waveClearTimer > 0) {
      this.waveClearTimer -= dt
      if (this.waveClearTimer <= 0) {
        this.state = 'boon'
        this.ui.showBoons(this.wave, this.boonChoices, this.waveReward, () => {})
        this.ui.dom.hud.style.opacity = '.1'
        if (document.pointerLockElement) document.exitPointerLock()
      }
    }
  }

  rollBoons() {
    const owned = new Set(this.boons.map(b => b.id))
    const pool = BOONS.filter(b => !owned.has(b.id) || ['iron-skin', 'keen-edge', 'bloodthirst'].includes(b.id))
    const out = []
    while (out.length < 3 && pool.length) {
      const idx = Math.floor(Math.random() * pool.length)
      out.push(pool.splice(idx, 1)[0])
    }
    return out
  }

  chooseBoon(boon) {
    if (!boon) return
    this.boons.push(boon)
    boon.apply(this)
    this.audio.unlock()
    this.ui.toast(`${boon.name} CLAIMED`, 'gold')
    this.waveRage = boon.id === 'blood-price' ? 40 : 0
    this.heal(Math.min(14, this.maxHealth - this.player.health), true)
  }

  nextWave() {
    if (this.state !== 'boon') return
    this.ui.closeAllOverlays()
    this.ui.dom.hud.style.opacity = ''
    this.state = 'playing'
    this.wave++
    this.stamina = this.maxStamina
    this.rage = Math.min(100, this.rage + 14)
    this.startWave(this.wave)
    this.requestLock()
  }

  abandonRun() {
    this.ui.closeAllOverlays()
    this.toTitle()
  }

  toTitle() {
    this.state = 'title'
    this.clearEnemies()
    this.ui.hideGameUI()
    this.ui.showTitle()
    this.ui.dom.hud.style.opacity = ''
    this.ui.updateTitleLoadout(this.meta)
    this.spawnPlayer()
    this.player.root.position.set(0, 0, 3.1)
    this.player.root.rotation.y = .16
    this.arena.build(0)
    this.themeIndex = 0
    this.yaw = .4
    this.pitch = .1
    this.timeScale = 1
    this.execution = null
    this.deathShown = false
    this.ui.hideDeath()
    if (document.pointerLockElement) document.exitPointerLock()
  }

  updateHazards(dt) {
    for (const h of this.arena.hazards) {
      if (!h.active) continue
      const candidates = []
      if (!this.player.dead) candidates.push({ obj: this.player.root.position, player: true })
      for (const e of this.enemies) if (!e.char.dead) candidates.push({ e, obj: e.char.root.position })
      for (const c of candidates) {
        const dist = Math.hypot(c.obj.x - h.position.x, c.obj.z - h.position.z)
        if (dist < 1.35) {
          if (c.player) {
            if (this.hazardCooldown <= 0 && this.playerInvuln <= 0) {
              this.hazardCooldown = .65
              this.damagePlayer(21, null, true)
              this.ui.toast('IMPALED', 'blood')
              this.effects.bloodBurst(c.obj.clone().setY(.5), new THREE.Vector3(0, 1, 0), 24, 1)
            }
          } else {
            if (!c.e.hazardCd || c.e.hazardCd <= 0) {
              c.e.hazardCd = .7
              const result = c.e.char.takeHit(42, { heavy: true, breakPower: 1.5 })
              if (result) {
                this.effects.bloodBurst(c.e.char.getChestPosition(), new THREE.Vector3(0, 1, 0), 18, 1)
                this.audio.hit(1.2, true)
                if (result.killed) this.onEnemyKilled(c.e, true)
              }
            }
          }
        }
      }
    }
    for (const e of this.enemies) if (e.hazardCd > 0) e.hazardCd -= dt
  }

  updateCamera(dtReal) {
    const cam = this.camera
    let desiredPos = new THREE.Vector3()
    let look = new THREE.Vector3()
    let fov = 55
    if (this.state === 'title') {
      const t = this.realTime
      const a = .42 + Math.sin(t * .055) * .1
      const r = 7.8 - Math.sin(t * .12) * .15
      desiredPos.set(Math.sin(a) * r, 2.85 + Math.sin(t * .21) * .08, 3.1 + Math.cos(a) * r)
      look.set(0, 1.35, 3.1)
      cam.position.lerp(desiredPos, 1 - Math.exp(-4 * dtReal))
      cam.lookAt(look)
      cam.fov = 47
      cam.updateProjectionMatrix()
      this.rimLight.position.set(desiredPos.x, 2.8, desiredPos.z + 1)
      this.playerLight.position.set(-desiredPos.x * .4, 3, desiredPos.z)
    } else if (this.execution) {
      const ex = this.execution
      const target = ex.enemy.char.getChestPosition()
      const mid = this.player.root.position.clone().lerp(ex.enemy.char.root.position, .5)
      const side = new THREE.Vector3(Math.cos(this.player.root.rotation.y), 0, -Math.sin(this.player.root.rotation.y))
      const k = clamp(ex.time / .9, 0, 1)
      desiredPos.copy(mid).addScaledVector(side, 2.6 + k * .2).add(new THREE.Vector3(0, 1.5 + Math.sin(ex.time * 2) * .03, 0))
      look.copy(target)
      cam.position.lerp(desiredPos, 1 - Math.exp(-5 * dtReal))
      cam.lookAt(look)
      cam.fov = 38 + Math.sin(k * Math.PI) * 4
      cam.updateProjectionMatrix()
    } else if (this.state === 'dead') {
      const t = this.deathTimer
      const p = this.player.root.position
      desiredPos.set(p.x + Math.sin(t * .3) * 4.3, 2.2 + Math.min(1.6, t * .35), p.z + Math.cos(t * .3) * 4.3)
      cam.position.lerp(desiredPos, 1 - Math.exp(-2 * dtReal))
      cam.lookAt(p.x, .7, p.z)
      cam.fov = 48
      cam.updateProjectionMatrix()
    } else {
      const baseTarget = this.player.root.position.clone().setY(1.48)
      const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
      const right = new THREE.Vector3(-Math.cos(this.yaw), 0, Math.sin(this.yaw))
      let dist = this.cameraDist * (1 + this.intro * .75)
      const horiz = dist * Math.cos(this.pitch)
      desiredPos.copy(baseTarget)
        .addScaledVector(forward, -horiz)
        .addScaledVector(right, this.cameraShoulder)
        .add(new THREE.Vector3(0, dist * Math.sin(this.pitch) + .15, 0))
      look.copy(baseTarget).addScaledVector(forward, 7).add(new THREE.Vector3(0, .08, 0))
      if (this.intro > 0) {
        this.intro = Math.max(0, this.intro - dtReal * 1.5)
        cam.position.lerp(desiredPos, 1 - Math.exp(-3.6 * dtReal))
      } else {
        cam.position.copy(desiredPos)
      }
      cam.lookAt(look)
      const sprinting = this.keys.sprint && this.player.speedActual > 2
      fov = 55 + (sprinting ? 3.5 : 0) + (this.player.state === 'attack' ? 1.2 : 0)
      cam.fov = damp(cam.fov, fov, 4, dtReal)
      cam.updateProjectionMatrix()
      this.rimLight.position.set(this.player.root.position.x + 2.4, 3.2, this.player.root.position.z + 1.5)
      this.playerLight.position.set(this.player.root.position.x - 1.6, 2.4, this.player.root.position.z - 2)
    }
    if (this.shakeEnabled) {
      const s = this.effects.getShake(dtReal)
      cam.position.x += s.x; cam.position.y += s.y
    }
  }

  updateHUD(dtReal) {
    this.uiTimer -= dtReal
    if (this.uiTimer > 0) return
    this.uiTimer = .075
    const executable = !!this.execution || this.rage >= this.executeCost && this.enemies.some(e => !e.char.dead && e.char.health / e.char.maxHealth < (e.boss ? .16 : .34) && e.char.root.position.distanceTo(this.player.root.position) < 3.4)
    if (!this.execution) this.ui.updateHUD({
      health: Math.max(0, this.player.health), maxHealth: this.maxHealth,
      stamina: this.stamina, maxStamina: this.maxStamina,
      armor: this.player.armor, maxArmor: this.player.maxArmor,
      combo: this.combo, score: this.score, runMarks: this.runMarks,
      chain: this.chain, chainTimer: this.chainTimer / 1.7,
      rage: this.rage, weaponName: this.weapon.name,
      reach: this.weapon.reach, damage: this.weapon.damage,
      executable, slowmo: this.slowmoTimer > 0 || !!this.execution
    })
    this.ui.setReticle(!!this.closestEnemyInFront(4.4, .55))
    this.ui.updateEnemyBars(this.enemies, this.camera)
  }

  update(dtReal) {
    this.realTime += dtReal
    this.time += dtReal
    const dt = dtReal * this.timeScale
    if (this.settings.motion) this.bloom.strength = .32
    if (this.state === 'title') {
      this.arena.update(dtReal, .05)
      this.player.update(dtReal)
      this.player.speedActual = 0
      this.effects.update(dtReal, this.camera)
      this.updateCamera(dtReal)
      this.audio.update(dtReal, .08, false)
      return
    }
    if (this.state === 'paused' || this.state === 'boon' || (this.state === 'title')) {
      this.arena.update(dtReal * .25, .12)
      this.effects.update(dtReal * .25, this.camera)
      return
    }
    if (this.state === 'executing') {
      this.updateExecution(dtReal)
      this.arena.update(dt * .5, .6)
      this.effects.update(dt * .5, this.camera)
      this.updateCamera(dtReal)
      this.updateHUD(dtReal)
      this.audio.update(dtReal, .8, false)
      return
    }
    if (this.state === 'dead') {
      this.deathTimer += dtReal
      this.player.update(dt)
      this.arena.update(dt, .1)
      this.effects.update(dt, this.camera)
      this.updateCamera(dtReal)
      if (this.deathTimer > 2.4 && !this.deathShown) {
        this.deathShown = true
        this.timeScale = 1
        this.ui.showSlowmo(false)
        this.ui.showDeath({
          wave: this.wave, kills: this.kills, score: this.score, marks: this.runMarks,
          boss: this.enemies.find(e => e.boss && !e.char.dead)?.def.name
        })
      }
      this.audio.update(dtReal, .1, false)
      return
    }
    // playing
    if (this.slowmoTimer > 0) this.slowmoTimer -= dtReal
    if (this.hitstop > 0) { this.hitstop -= dtReal; this.freezeTimer = 1 }
    else this.freezeTimer = 0
    const worldDt = this.freezeTimer ? dt * .08 : dt
    this.timeScale = damp(this.timeScale, this.slowmoTimer > 0 ? .35 : 1, 18, dtReal)
    if (this.freezeTimer) this.timeScale = .08
    const stepDt = dtReal * this.timeScale
    this.updateSpawns(dtReal)
    this.updatePlayer(stepDt)
    this.updateEnemies(stepDt)
    this.updateHazards(stepDt)
    this.updateWave(dtReal)
    this.arena.update(stepDt, clamp(1 - this.enemies.filter(e => !e.char.dead).length / 6, .1, 1))
    this.effects.update(stepDt, this.camera)
    this.updateCamera(dtReal)
    this.updateHUD(dtReal)
    const close = this.enemies.filter(e => !e.char.dead && e.char.root.position.distanceTo(this.player.root.position) < 9).length
    const intensity = clamp(.12 + close * .19 + this.combo * .03, 0, 1)
    this.audio.update(dtReal, intensity, this.player.speedActual > .5)
    if (this.settings.gore >= 2 && this.player.health < this.maxHealth * .3) this.ui.dom.blood.classList.add('active')
    else if (!this.settings.gore) this.ui.dom.blood.classList.remove('active')
  }

  render() {
    this.composer.render()
  }

  animate() {
    requestAnimationFrame(this.animate)
    const dt = Math.min(this.clock.getDelta(), .05)
    this.update(dt)
    this.render()
  }
}

