.menu-btn.primary .menu-note { color: var(--blood-bright); }

.title-loadout { position: absolute; left: 6vw; bottom: 11.7%; width: min(315px, 24vw); padding: 16px 0; border-top: 1px solid var(--line); border-bottom: 1px solid rgba(181,141,79,.13); }
.title-loadout .panel-kicker { font-size: 9px; }
.loadout-row { display: flex; align-items: center; gap: 14px; margin: 11px 0 13px; }
.weapon-glyph { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid rgba(181,141,79,.26); background: linear-gradient(145deg, rgba(181,141,79,.1), transparent); color: #d3c29e; font-size: 19px; transform: rotate(-8deg); }
.loadout-row strong { display: block; font-family: var(--serif); font-size: 12px; letter-spacing: .12em; color: #dbd0bc; font-weight: 600; }
.loadout-row span { display: block; margin-top: 5px; font-size: 10px; letter-spacing: .17em; color: #7d7362; }
.progress-line { height: 2px; background: rgba(255,255,255,.07); }
.progress-line i { display: block; height: 100%; background: linear-gradient(90deg, var(--blood), var(--gold)); }
.progress-meta { display: flex; justify-content: space-between; margin-top: 7px; color: #6e6455; font-size: 9px; letter-spacing: .22em; }

.title-footer { position: absolute; left: 4.5vw; right: 4.5vw; bottom: calc(24px + var(--safe-bottom)); display: flex; justify-content: space-between; align-items: center; font-size: 9px; letter-spacing: .23em; color: #665d50; }
.footer-mid { display: flex; align-items: center; gap: 12px; color: #8f8169; }
.footer-mid i { width: 3px; height: 3px; background: var(--blood-bright); transform: rotate(45deg); }

/* ---------- HUD ---------- */
.hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; opacity: 0; transition: opacity .65s ease; }
body.in-game .hud { opacity: 1; }
body.in-game .title-screen { opacity: 0; visibility: hidden; }
.hud-top-left { position: absolute; top: calc(31px + var(--safe-top)); left: 3.1vw; display: flex; gap: 12px; align-items: flex-start; filter: drop-shadow(0 2px 8px rgba(0,0,0,.8)); }
.portrait-mark { width: 43px; height: 52px; border: 1px solid rgba(195,160,97,.33); background: linear-gradient(160deg, rgba(168,48,28,.2), rgba(6,5,4,.7)); clip-path: polygon(50% 0, 100% 12%, 100% 78%, 50% 100%, 0 78%, 0 12%); display: grid; place-items: center; }
.portrait-mark span { font-family: var(--serif); color: var(--gold); font-size: 17px; }
.vitals { width: clamp(190px, 15.5vw, 260px); }
.vital { position: relative; margin-bottom: 6px; }
.vital-label { position: absolute; top: -1px; left: 8px; z-index: 2; font-size: 8px; letter-spacing: .3em; color: #d3c5ab; text-shadow: 0 1px 4px #000; }
.bar { height: 14px; background: rgba(4,3,2,.72); border: 1px solid rgba(192,159,100,.21); position: relative; overflow: hidden; transform: skewX(-15deg); }
.bar i { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; transition: width .14s ease-out; }
.bar em { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; background: rgba(222,210,185,.2); transition: width .75s ease; }
.health .bar i { background: linear-gradient(90deg, #5f100b, #a6261a 54%, #c8452f); box-shadow: 0 0 13px rgba(198,59,40,.5); }
.stamina .bar { height: 6px; }
.stamina .bar i { background: linear-gradient(90deg, #6c6540, #c2ad6d); }
.health-text { position: absolute; right: 7px; top: -1px; z-index: 2; font-size: 10px; font-weight: 600; color: #e8dcc2; }
.status-chips { display: flex; gap: 7px; margin-top: 5px; }
.status-chips span { font-size: 8px; letter-spacing: .2em; padding: 2px 6px; background: rgba(0,0,0,.35); border: 1px solid rgba(174,145,91,.18); color: #968872; }

.hud-top-center { position: absolute; top: calc(26px + var(--safe-top)); left: 50%; transform: translateX(-50%); text-align: center; filter: drop-shadow(0 2px 10px #000); }
.hud-top-center p { margin: 0 0 2px; color: #95866f; font-size: 9px; letter-spacing: .44em; }
.hud-top-center strong { display: block; font-family: var(--serif); font-size: 20px; letter-spacing: .28em; color: #dfd1b7; font-weight: 600; }
.hud-top-center span { display: block; margin-top: 4px; color: #756957; font-size: 8px; letter-spacing: .31em; }
.wave-pips { display: flex; justify-content: center; gap: 5px; margin-top: 8px; }
.wave-pips i { width: 13px; height: 2px; background: rgba(195,163,103,.18); }
.wave-pips i.filled { background: var(--gold); box-shadow: 0 0 6px rgba(181,141,79,.5); }
.wave-pips i.boss { background: var(--blood); }
.hud-top-right { position: absolute; top: calc(31px + var(--safe-top)); right: 3.1vw; text-align: right; filter: drop-shadow(0 2px 8px rgba(0,0,0,.8)); }
.score-block span { display: block; color: #776c5a; font-size: 8px; letter-spacing: .32em; }
.score-block b { display: block; font-family: var(--serif); font-size: 18px; letter-spacing: .11em; color: #d9cbb3; font-weight: 600; }

