```js
export function createClothTexture(size=256) {
  const [c,ctx]=canvas(size)
  const img=ctx.createImageData(size,size)
  const rng=seededRandom(301)
  const noise=seededNoise2D(44)
  for y,x:
    const fold = Math.sin(x/size*Math.PI*6 + fbm(noise,x/40,y/40,2)*2)*.5+.5
    const weave = ((x%3===0?1:0)+(y%3===0?1:0))*3
    const v = 200 + fbm(noise,x/12,y/12,3)*30 - fold*34 - weave
    data = v
  ctx.putImageData
  // stains
  for i<16: radial dark
  const tex=texture(c,1,true)
  return tex
}
```
Careful alpha.

Then character.js import `createClothTexture`; module-level `let clothTexture=null`; clothMat sets map.
